  var RECEIPT_FIELDS = {invoiceNo:'Invoice number',dpDate:'Down payment date',contact:'Guest contact',address:'Guest address',pax:'Guest count',marketer:'Agent',mode:'Payment method',additionalFees:'Additional fees'};
