  function fillResortSelects() {
    var all = CFG.resorts.map(function(r){ return r.name; });
    var active = CFG.resorts.filter(function(r){ return r.active; }).map(function(r){ return r.name; });
    if (!active.length) active = all;
    fillSelect('resort', active, false);
    fillSelect('qdResort', active, false);
    fillSelect('calResort', all, false);
    fillSelect('upResort', all, true, 'All Resorts');
    fillSelect('repResort', all, true, 'All Resorts');
    fillSelect('exfResort', all, true, 'All Resorts');
    fillSelect('ex_resort', all, false);
    fillSelect('admResort', all, false);
    if (!$('resort').value && active.length) $('resort').value = active[0];
    if (!$('qdResort').value && active.length) $('qdResort').value = active[0];
  }
  function applyBusinessText() {
    $('menuSub').textContent = CFG.settings.businessName + '. What would you like to do?';
    $('agentWrap').style.display = CFG.settings.agentEnabled ? '' : 'none';
  }
  function buildModeOptions() {
    var cur = $('mode').value, list = (CFG.settings.paymentModes && CFG.settings.paymentModes.length) ? CFG.settings.paymentModes : ['Cash'];
    var h = '<option value="">Select...</option>' + list.map(function(m){ return '<option>' + esc(m) + '</option>'; }).join('');
    $('mode').innerHTML = h;
    if (cur && list.indexOf(cur) < 0) $('mode').insertAdjacentHTML('beforeend', '<option>' + esc(cur) + '</option>');
    $('mode').value = cur;
    PROOF_MODES = CFG.settings.proofModes || [];
  }
  function applyConfig(cfg) {
    if (cfg.license) renderSub(cfg.license);
    CFG = cfg; CUR = cfg.settings.currency || '₱';
    RESORTS = {};
    cfg.resorts.forEach(function(r){ RESORTS[r.name] = r; });
    DEFAULT_RESORT = cfg.defaultResort || (cfg.resorts[0] && cfg.resorts[0].name) || '';
    fillResortSelects(); buildAgentOptions(); applyBusinessText(); buildModeOptions(); buildTypeOptions();
    if ($('resort').value) { applyResortUI(); mountReceipt($('receipt'), $('resort').value); }
    CFG_READY = true;
    renderUpcomingSummary(); renderBanner(); renderClientReferral(LIC && LIC.referral);
  }
  function loadConfig(cb) {
    if (!(window.google && google.script)) return;
    RUN
      .withSuccessHandler(function(cfg){ applyConfig(cfg); loadBookingTypes(); loadFees(); if (cb) cb(); })
      .withFailureHandler(function(e){ if (authFail(e)) return; menuNote('Could not load the settings: ' + e.message); })
      .getAppConfig(TOKEN);
  }

  function onResortChange() {
    CUSTOM_FIELD_KEYS.forEach(function(key){$(key).value='';});
    var cur = detailOf(domRows()), list = currentFees(), keep = {};
    list.forEach(function(f){ if (cur[f.name]) keep[f.name] = cur[f.name]; });
    applyResortUI();
    mountReceipt($('receipt'), $('resort').value);
    renderFeeList(list, keep);
    buildTypeOptions();
    applyBookType(false);      // recompute check-in/out with this resort's times
    if (!editing && !savedInvoice) { invoiceRequest++; $('invoiceNo').value=''; }
    update(); fitPreview(); checkConflict();
  }

  /* ---------- formatting helpers ---------- */
  function peso(v) {
    if (v === '' || v === null || isNaN(v)) return '';
    return CUR + Number(v).toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  }
  function fmtDate(v) {
    if (!v) return '';
    var d = new Date(v + 'T00:00:00');
    return d.toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'});
  }
  function fmtDateTime(v) {
    if (!v) return '';
    var d = new Date(v);
    return d.toLocaleDateString('en-US', {month:'short', day:'numeric', year:'numeric'}) + ', ' +
           d.toLocaleTimeString('en-US', {hour:'numeric', minute:'2-digit'});
  }
  function addFeeText(v) {
    if (v === '') return '';
    return /^[\d.,\s]+$/.test(v) ? peso(parseFloat(v.replace(/,/g,''))) : v;
  }

  /* ---------- live preview ---------- */
  /* ---------- additional fees ---------- */
  function feesFor(resort) {
    return fees.filter(function(f){ return !f.resort || f.resort === 'Both' || f.resort === (resort || DEFAULT_RESORT); });
  }
  function currentFees() { return feesFor($('resort').value); }
  var fees = [];     // loaded from the Fees sheet
  var CHECK_SVG = '<svg width="16" height="16" viewBox="0 0 16 16"><circle cx="8" cy="8" r="8" fill="#1b9a3c"/><path d="M4.2 8.3l2.6 2.6 5-5.4" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  var CROSS_SVG = '<svg width="16" height="16" viewBox="0 0 16 16"><circle cx="8" cy="8" r="8" fill="#d9363e"/><path d="M5 5l6 6M11 5l-6 6" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>';
  function attr(t) { return esc(String(t)).replace(/"/g, '&quot;'); }
  function parseDetail(t) { try { var o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
  function pesoShort(n) { return CUR + Number(n).toLocaleString('en-US', {maximumFractionDigits:2}); }
  function feeLabel(r) { return r.name + ' (' + pesoShort(r.p) + (r.d ? ' ' + r.d : '') + ')'; }
  // Rows = current fee list, with saved selections/prices applied. Fees that were booked but later removed stay listed.
  function buildFeeRows(list, detail) {
    var rows = list.map(function(f){
      var det = detail[f.name];
      return {name:f.name, p: det ? Number(det.p) : f.amount, d: det && det.d !== undefined ? det.d : f.desc,
              q: det ? (parseInt(det.q, 10) || 1) : 1, on: !!det};
    });
    Object.keys(detail).forEach(function(n){
      if (!list.some(function(f){ return f.name === n; })) {
        var det = detail[n];
        rows.push({name:n, p:Number(det.p) || 0, d:det.d || '', q:parseInt(det.q, 10) || 1, on:true});
      }
    });
    return rows;
  }
  function renderFeeList(list, detail) {
    var rows = buildFeeRows(list, detail);
    $('feeList').innerHTML = rows.length ? rows.map(function(r){
      return '<label class="fee-row" data-name="' + attr(r.name) + '" data-p="' + r.p + '" data-d="' + attr(r.d) + '">' +
        '<input type="checkbox" class="fee-cb"' + (r.on ? ' checked' : '') + '>' +
        '<span class="fee-name">' + esc(r.name) + '<small>' + esc(pesoShort(r.p) + (r.d ? ' ' + r.d : '')) + '</small></span>' +
        '<input type="number" class="fee-qty" min="1" value="' + r.q + '" title="Quantity"' + (r.on ? '' : ' style="display:none"') + '></label>';
    }).join('') : '<div style="padding:8px 0;color:var(--muted);font-size:13px">No additional fees set up.</div>';
    applyPaymentLock();
  }
  function domRows() {
    return Array.prototype.map.call(document.querySelectorAll('#feeList .fee-row'), function(el){
      var q = parseInt(el.querySelector('.fee-qty').value, 10);
      return {name: el.getAttribute('data-name'), p: parseFloat(el.getAttribute('data-p')) || 0,
              d: el.getAttribute('data-d') || '', q: q > 0 ? q : 1, on: el.querySelector('.fee-cb').checked};
    });
  }
  function feesTotal(rows) { return rows.reduce(function(t, r){ return t + (r.on ? r.p * r.q : 0); }, 0); }
  function detailOf(rows) { var o = {}; rows.forEach(function(r){ if (r.on) o[r.name] = {q:r.q, p:r.p, d:r.d}; }); return o; }
  function summaryOf(rows) {
    return rows.filter(function(r){ return r.on; }).map(function(r){
      return r.name + (r.q > 1 ? ' x' + r.q : '') + ' (' + pesoShort(r.p * r.q) + ')';
    }).join('; ');
  }
  function renderReceiptFees(root, rows) {
    var ul = root.querySelector('#p_feeList'); if (!ul) return;
    ul.innerHTML = rows.map(function(r){
      return '<li>' + (r.on ? CHECK_SVG : CROSS_SVG) + '<span>' + esc(feeLabel(r)) + (r.on && r.q > 1 ? ' &times; ' + r.q : '') + '</span></li>';
    }).join('');
  }
  function setFeeCell(root, rows, legacyText) {
    var cell = root.querySelector('#p_additionalFees'); if (!cell) return;
    var on = rows.filter(function(r){ return r.on; });
    if (!on.length) { cell.textContent = legacyText || 'None'; return; }
    cell.innerHTML = '<b>' + esc(peso(feesTotal(rows))) + '</b><div class="fee-sum">' +
      esc(on.map(function(r){ return r.name + (r.q > 1 ? ' x' + r.q : ''); }).join(', ')) + '</div>';
  }
  function loadFees() {
    if (!(window.google && google.script)) return;
    RUN.withSuccessHandler(function(list){
      var keep = detailOf(domRows());
      fees = list || []; renderFeeList(currentFees(), keep); update(); fitPreview();
    }).getFees(TOKEN);
  }

  /* ---------- agent referral ---------- */
  function referredVal() { var r = document.querySelector('input[name=referred]:checked'); return r ? r.value : 'No'; }
  function pctVal() {
    var r = document.querySelector('input[name=agentPct]:checked');
    if (!r) return '';
    if (r.value === 'other') { var v = parseFloat($('agentPctOther').value); return isNaN(v) ? '' : v; }
    return parseFloat(r.value);
  }
  function agentNameVal() { return referredVal() === 'Yes' ? $('marketer').value.trim() : ''; }
  // Agent pay = percentage of the Booking Fee only (additional fees are NOT included)
  function agentPayVal() {
    if (referredVal() !== 'Yes') return '';
    var fee = parseFloat($('bookingFee').value), p = pctVal();
    if (isNaN(fee) || p === '' || isNaN(p)) return '';
    return Math.round(fee * p) / 100;
  }
  function setReferred(v) { var r = document.querySelector('input[name=referred][value="' + v + '"]'); if (r) r.checked = true; }
  function buildAgentOptions() {
    var st = CFG.settings, h = '';
    st.agentOptions.forEach(function(p){ h += '<label class="rd"><input type="radio" name="agentPct" value="' + p + '"> ' + p + '%</label>'; });
    h += '<label class="rd"><input type="radio" name="agentPct" value="other"> Other</label>' +
         '<input id="agentPctOther" type="number" min="0" max="100" step="0.1" placeholder="%" style="display:none;width:80px;padding:7px 8px">';
    $('pctRadios').innerHTML = h;
    $('agentPctOther').addEventListener('input', update);
    setPct(st.agentDefault);
    if (!st.agentEnabled) setReferred('No');
  }
  function setPct(v) {
    if (!document.querySelector('input[name=agentPct][value="other"]')) return;
    var n = parseFloat(v), std = CFG.settings.agentOptions;
    if (isNaN(n)) n = CFG.settings.agentDefault;
    if (std.indexOf(n) > -1) { document.querySelector('input[name=agentPct][value="' + n + '"]').checked = true; $('agentPctOther').value = ''; }
    else { document.querySelector('input[name=agentPct][value="other"]').checked = true; $('agentPctOther').value = n; }
  }
  function showAgentUI() {
    var yes = referredVal() === 'Yes';
    $('agentBox').style.display = yes ? '' : 'none';
    var oth = document.querySelector('input[name=agentPct][value="other"]');
    if (!oth) return;
    var other = oth.checked;
    $('agentPctOther').style.display = other ? '' : 'none';
    var pay = agentPayVal(), p = pctVal();
    $('agentPay').innerHTML = !yes ? '' : (pay === '' ? 'Agent Pay: <small>enter the booking fee and percentage</small>'
      : 'Agent Pay: ' + esc(peso(pay)) + ' <small>(' + p + '% of the ' + esc(peso(parseFloat($('bookingFee').value))) + ' booking fee, additional fees not included)</small>');
  }

  function receiptMap(d) {
    var fee = parseFloat(d.bookingFee), dp = parseFloat(d.downPayment), bal = parseFloat(d.balance);
    if (isNaN(bal) && !isNaN(fee)) bal = fee - (isNaN(dp) ? 0 : dp);
    var ci = d.checkIn || '', co = d.checkOut || '';
    return {
      name: d.name || '', contact: d.contact || '', address: d.address || '', invoiceNo: d.invoiceNo || '',
      dpDate: fmtDate(d.dpDate || d.bookingDate), bookingDate: fmtDate(d.dpDate || d.bookingDate), stayDate: fmtDate(ci.slice(0, 10)),
      bookingFee: peso(fee), downPayment: peso(dp), balance: peso(bal),
      mode: d.mode || '', checkIn: fmtDateTime(ci), checkOut: fmtDateTime(co),
      pax: d.pax || '', marketer: d.marketer || '',
      roomsIncluded:d.roomsIncluded === undefined || d.roomsIncluded === null ? '' : String(d.roomsIncluded),
      extraField1:d.extraField1 === undefined || d.extraField1 === null ? '' : String(d.extraField1),
      extraField2:d.extraField2 === undefined || d.extraField2 === null ? '' : String(d.extraField2),
      extraField3:d.extraField3 === undefined || d.extraField3 === null ? '' : String(d.extraField3)
    };
  }
  function fillMap(root, map) {
    for (var k in map) { var el = root.querySelector('#p_' + k); if (el) el.textContent = map[k]; }
    applyCustomReceiptVisibility(root);
  }

  function update() {
    var fee = parseFloat($('bookingFee').value);
    var dp  = parseFloat($('downPayment').value);
    var frozen = editing && editing.financialLocked && editing.financial;
    var rows = domRows(), ft = frozen ? Number(frozen.feesTotal)||0 : feesTotal(rows);
    $('additionalFees').value = frozen ? frozen.additionalFees : summaryOf(rows);
    $('feesDetail').value = frozen ? frozen.feesDetail : JSON.stringify(detailOf(rows));
    $('feeTotal').textContent = ft || rows.some(function(r){ return r.on; }) ? 'Additional fees total: ' + peso(ft) : '';
    var bal = frozen ? Number(frozen.balance)||0 : (isNaN(fee) ? '' : (fee + ft - (isNaN(dp) ? 0 : dp)));
    $('balance').value = bal === '' ? '' : bal.toFixed(2);

    var root = $('receipt');
    fillMap(root, receiptMap({
      name: $('name').value, contact: $('contact').value, address: $('address').value, invoiceNo: $('invoiceNo').value,
      dpDate: $('dpDate').value, bookingDate: $('dpDate').value,
      bookingFee: $('bookingFee').value, downPayment: $('downPayment').value, balance: bal,
      mode: $('mode').value, checkIn: $('checkIn').value, checkOut: $('checkOut').value,
      pax: $('pax').value, marketer: agentNameVal(), roomsIncluded:$('roomsIncluded').value,extraField1:$('extraField1').value,extraField2:$('extraField2').value,extraField3:$('extraField3').value
    }));
    renderReceiptFees(root, rows);
    setFeeCell(root, rows, frozen && ft ? peso(ft) + (frozen.additionalFees ? ' - ' + frozen.additionalFees : '') : '');
    showAgentUI();
  }

  function fitPreview() {
    var wrap = $('previewWrap'), sc = $('scaler'), r = $('receipt');
    if (!wrap.clientWidth) return;
    var s = Math.min(1, wrap.clientWidth / 800);
    sc.style.transform = 'scale(' + s + ')';
    wrap.style.height = (r.offsetHeight * s) + 'px';
  }

  function setStatus(msg, cls) { var s = $('status'); s.textContent = msg; s.className = cls || ''; }

  /* ---------- payment proof ---------- */
  var proofData = '';
  var PROOF_MODES = ['GCash','Maya','Bank Transfer'];      // replaced by the Business settings
  function toggleProof() {
    var show = PROOF_MODES.some(function(m){ return m.toLowerCase() === String($('mode').value).toLowerCase(); }) && !!$('mode').value;
    $('proofBox').style.display = show ? 'block' : 'none';
    if (!show) clearProof();
  }
  function clearProof() { proofData = ''; $('proofFile').value = ''; $('proofPrev').style.display = 'none'; }
  function shrinkImage(file, cb) {
    var reader = new FileReader();
    reader.onload = function(e) {
      var img = new Image();
      img.onload = function() {
        var max = 1000, sc = Math.min(1, max / Math.max(img.width, img.height));
        var c = document.createElement('canvas');
        c.width = Math.round(img.width * sc); c.height = Math.round(img.height * sc);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        cb(c.toDataURL('image/jpeg', 0.75));
      };
      img.onerror = function(){ setStatus('Could not read that image.', 'err'); };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  }

  /* ---------- upcoming bookings / overlap ---------- */
  var upcoming = [];
  function loadUpcoming(cb) {
    if (!(window.google && google.script)) { upcoming = []; if (cb) cb(); return; }
    RUN.withSuccessHandler(function(list){ upcoming = list || []; checkConflict(); if (cb) cb(); })
      .withFailureHandler(function(e){ if (authFail(e)) return; setStatus('Could not load bookings: ' + e.message, 'err'); })
      .getUpcomingBookings(TOKEN);
  }
  function overlaps(b) {
    var a1 = $('checkIn').value, a2 = $('checkOut').value;
    if (!a1 || !a2) return false;
    if (b.status === 'Canceled') return false;
    if ((b.resort || DEFAULT_RESORT) !== $('resort').value) return false;
    if (b.invoiceNo === $('invoiceNo').value) return false;
    var s1 = a1.replace('T',' '), s2 = a2.replace('T',' ');
    return s1 < b.checkOut && s2 > b.checkIn;
  }
  function checkConflict() {
    var w = $('conflictWarn'), ok = $('conflictOk');
    w.style.display = ok.style.display = 'none';
    if (!$('checkIn').value || !$('checkOut').value) return;
    var hits = upcoming.filter(overlaps);
    if (hits.length) {
      w.innerHTML = 'Date conflict: ' + hits.map(function(b){
        return b.name + ' (' + fmtDateTime(b.checkIn.replace(' ','T')) + ' to ' + fmtDateTime(b.checkOut.replace(' ','T')) + ')';
      }).join('; ');
      w.style.display = 'block';
    } else { ok.style.display = 'block'; }
  }
  var showCanceled = false;
  function renderUpcoming() {
    var box = $('upList');
    var q = $('upSearch').value.trim().toLowerCase();
    var rf = $('upResort').value;
    var inScope = function(b){ return !rf || (b.resort || DEFAULT_RESORT) === rf; };
    var canceledCount = upcoming.filter(function(b){ return inScope(b) && b.status === 'Canceled'; }).length;
    $('btnToggleCanceled').textContent = (showCanceled ? 'Hide' : 'Show') + ' Canceled Bookings (' + canceledCount + ')';
    var rows = [];
    upcoming.forEach(function(b, i){
      if (!inScope(b)) return;
      if (b.status === 'Canceled' && !showCanceled) return;
      if (q && b.invoiceNo.toLowerCase().indexOf(q) < 0 && b.name.toLowerCase().indexOf(q) < 0) return;
      rows.push({b:b, i:i});
    });
    if (!rows.length) {
      box.innerHTML = '<div class="empty">' + (q ? 'No bookings match "' + esc($('upSearch').value.trim()) + '".' : (rf ? 'No upcoming bookings for ' + esc(rf) + '.' : 'No upcoming bookings found.')) + '</div>';
      return;
    }
    box.innerHTML = rows.map(function(r){
      var b = r.b, canceled = (b.status === 'Canceled');
      var c = overlaps(b);
      var pay = canceled ? '<span class="badge canceled">Canceled</span>'
        : (b.balance > 0
            ? '<span class="badge pending">Pending balance: ' + esc(peso(b.balance)) + '</span>'
            : '<span class="badge paid">Fully paid</span>');
      return '<div class="bk' + (canceled ? ' canceled' : (c ? ' conflict' : '')) + '"><b>' + esc(b.name) + '</b><span class="chip">' + esc(b.resort || DEFAULT_RESORT) + '</span>' + pay +
        (c ? '<span class="tag">Overlaps your dates</span>' : '') +
        '<div class="dt">In: ' + esc(fmtDateTime(b.checkIn.replace(' ','T'))) + '</div>' +
        '<div class="dt">Out: ' + esc(fmtDateTime(b.checkOut.replace(' ','T'))) + '</div>' +
        (b.bookType ? '<div class="dt">Type: ' + esc(TYPE_LABELS[b.bookType] || '') + '</div>' : '') + '<div class="dt">' + esc(b.invoiceNo) + (b.pax ? ' &middot; ' + esc(b.pax) + ' pax' : '') + '</div>' +
        (b.notes ? '<div class="up-notes"><b>Notes:</b> ' + esc(b.notes) + '</div>' : '') +
        '<div class="actions">' +
          (canceled ? '' : '<button type="button" class="btn-regen" data-i="' + r.i + '">Regenerate Receipt</button><button type="button" class="btn-edit" data-i="' + r.i + '">Modify</button><button type="button" class="btn-cancel" data-i="' + r.i + '">Cancel Booking</button>') +
          '<button type="button" class="btn-delperm" data-i="' + r.i + '">Delete</button></div></div>';
    }).join('');
  }
  var pendingDelete = null;
  function askDelete(i) {
    pendingDelete = upcoming[i];
    $('confirmText').textContent = 'Booking of ' + pendingDelete.name + ' (' + pendingDelete.invoiceNo + '), ' +
      fmtDateTime(pendingDelete.checkIn.replace(' ','T')) + ' to ' + fmtDateTime(pendingDelete.checkOut.replace(' ','T')) + '.';
    $('btnDelete').disabled = false; $('btnDelete').textContent = 'Yes, Cancel Booking';
    $('confirmBg').style.display = 'flex';
  }
  function doDelete() {
    if (!pendingDelete) return;
    var inv = pendingDelete.invoiceNo;
    $('btnDelete').disabled = true; $('btnDelete').textContent = 'Canceling...';
    RUN
      .withSuccessHandler(function(res){
        $('confirmBg').style.display = 'none';
        if (!res.ok) { setStatus(res.message, 'err'); }
        else {
          setStatus('Booking ' + inv + ' was canceled.', 'ok');
          if (savedInvoice === inv) savedInvoice = '';
        }
        pendingDelete = null;
        $('upList').innerHTML = '<div class="empty">Refreshing...</div>';
        loadUpcoming(renderUpcoming);
      })
      .withFailureHandler(function(e){ if (authFail(e)) return;
        $('confirmBg').style.display = 'none';
        setStatus('Could not cancel: ' + e.message, 'err');
      })
      .cancelBooking(TOKEN, inv);
  }
  /* ---------- permanent delete (needs a random 6-digit number typed back) ---------- */
  var pendingPermDelete = null, permCode = '';
  function permDeleteReady() { $('btnDelBkGo').disabled = !(permCode && $('delBkInput').value.length === 6); }
  function askPermDelete(i) {
    var b = upcoming[i];
    if (!b) return;
    if (!(window.google && google.script)) return;
    pendingPermDelete = b; permCode = '';
    $('delBkText').textContent = 'Booking of ' + b.name + ' (' + b.invoiceNo + '), ' + b.resort + ', ' +
      fmtDateTime(b.checkIn.replace(' ','T')) + ' to ' + fmtDateTime(b.checkOut.replace(' ','T')) + '.';
    $('delBkCode').textContent = '------'; $('delBkInput').value = ''; $('delBkMsg').textContent = '';
    permDeleteReady();
    $('delBkBg').style.display = 'flex';
    RUN
      .withSuccessHandler(function(r){
        if (!pendingPermDelete || pendingPermDelete.invoiceNo !== b.invoiceNo) return;
        if (!r.ok) { $('delBkMsg').textContent = r.message; return; }
        permCode = r.code; $('delBkCode').textContent = r.code; $('delBkInput').focus(); permDeleteReady();
      })
      .withFailureHandler(function(e){ if (authFail(e)) return; $('delBkMsg').textContent = 'Could not start the delete: ' + e.message; })
      .requestBookingDelete(TOKEN, b.invoiceNo);
  }
  function closePermDelete() { $('delBkBg').style.display = 'none'; pendingPermDelete = null; permCode = ''; $('delBkInput').value = ''; $('delBkCode').textContent = '------'; }
  function doPermDelete() {
    if (!pendingPermDelete || !permCode) return;
    var typed = $('delBkInput').value.trim();
    if (typed !== permCode) { $('delBkMsg').textContent = 'That number does not match. Please type the number shown above.'; return; }
    var inv = pendingPermDelete.invoiceNo, btn = $('btnDelBkGo');
    setBusy(btn, true, 'Deleting...'); $('delBkMsg').textContent = '';
    RUN
      .withSuccessHandler(function(r){
        setBusy(btn, false);
        if (!r.ok) {
          $('delBkMsg').textContent = r.message;
          if (r.expired) { permCode = ''; $('delBkCode').textContent = '------'; }
          permDeleteReady(); return;
        }
        closePermDelete();
        if (savedInvoice === inv) savedInvoice = '';
        upMsg('Booking ' + inv + ' was permanently deleted.', 'ok');
        $('upList').innerHTML = '<div class="empty">Refreshing...</div>';
        loadUpcoming(renderUpcoming);
      })
      .withFailureHandler(function(e){ setBusy(btn, false); if (authFail(e)) return; $('delBkMsg').textContent = 'Could not delete: ' + e.message; permDeleteReady(); })
      .deleteBooking(TOKEN, inv, typed);
  }

  function openUpcoming() {
    $('modalBg').style.display = 'flex';
    $('upSearch').value = ''; $('upResort').value = ''; showCanceled = false; upMsg('');
    $('upList').innerHTML = '<div class="empty">Loading...</div>';
    loadUpcoming(renderUpcoming);
  }

  /* ---------- duplicate invoice ---------- */
  function showInvNotice(msg) { var n = $('invNotice'); n.textContent = msg; n.style.display = msg ? 'block' : 'none'; }
  var invoiceRequest = 0;
  function requestInvoice() {
    showInvNotice('');
    var resort = $('resort').value, seq = ++invoiceRequest;
    if (RC().invoiceMode === 'Manual') { $('invoiceNo').value = ''; update(); return; }
    if (!(window.google && google.script)) { $('invoiceNo').value = (RC().invoicePrefix || CFG.settings.invoicePrefix || 'INV#') + '00001'; update(); return; }
    RUN.withSuccessHandler(function(n){ if (seq !== invoiceRequest || resort !== $('resort').value || editing || savedInvoice) return; $('invoiceNo').value = n; update(); })
      .withFailureHandler(function(e){ if (!authFail(e)) showInvNotice('Could not get an invoice number: ' + e.message); }).getNextInvoiceNo(TOKEN, resort);
  }
  function verifyInvoice() {
    var v = $('invoiceNo').value.trim(), resort = $('resort').value;
    if (!(window.google && google.script) || editing || v === savedInvoice) return;
    if (!v) return;
    RUN.withSuccessHandler(function(res){
      if (resort !== $('resort').value || v !== $('invoiceNo').value.trim()) return;
      if (res.exists) {
        if (res.manual) { showInvNotice('Invoice ' + v + ' is already used. Enter a different number.'); return; }
        requestInvoice(); showInvNotice('That invoice is already used. The next available number will be used.');
      } else showInvNotice('');
    }).withFailureHandler(function(e){ if (!authFail(e)) showInvNotice(e.message); }).checkInvoice(TOKEN, v, resort);
  }

  /* ---------- new booking ---------- */
  function newBooking() {
    FIELDS.forEach(function(f){ $(f).value = ''; });
    $('stayDate').value = ''; $('bookType').value = ''; applyBookType(false);
    setReferred('No'); setPct(CFG.settings.agentDefault);
    editing = null; $('invoiceNo').readOnly = false; applyEditUI();
    renderFeeList(currentFees(), {});
    clearProof(); toggleProof(); checkConflict(); savedInvoice = ''; showInvNotice('');
    var t = new Date(); $('dpDate').value = t.getFullYear() + '-' + ('0'+(t.getMonth()+1)).slice(-2) + '-' + ('0'+t.getDate()).slice(-2);
    update(); fitPreview(); setStatus('');
    applyResortUI(); invoiceRequest++;
  }

  /* ---------- image export ---------- */
  function downloadImage(root, invoiceNo, guestName) {
    var session = TOKEN;
    var clone = (root || $('receipt')).cloneNode(true);
    clone.removeAttribute('id');
    var holder = document.createElement('div');
    holder.style.cssText = 'position:fixed;left:-10000px;top:0;width:800px;';
    holder.appendChild(clone);
    document.body.appendChild(holder);
    var resumeFit = window.PhoneFit ? PhoneFit.suspend() : function(){};   // draw the image at normal scale (see PHONE FIT)
    return html2canvas(clone, {scale:2, backgroundColor:'#ffffff', useCORS:true})
      .then(function(canvas){ resumeFit(); return canvas; }, function(e){ resumeFit(); throw e; })
      .then(function(canvas){
      document.body.removeChild(holder);
      if (session !== TOKEN) throw new Error('The session changed before the confirmation could download.');
      var inv = String(invoiceNo !== undefined ? invoiceNo : $('invoiceNo').value).replace(/[^\w.-]+/g, '') || 'confirmation';
      var name = String(guestName !== undefined ? guestName : $('name').value || 'guest').replace(/[^a-z0-9]+/gi, '_');
      var file = 'Booking_' + inv + '_' + name + '.png';
      var a = document.createElement('a');
      a.download = file; a.href = canvas.toDataURL('image/png');
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
    });
  }

  /* ---------- regenerate a saved booking's receipt (does not touch the form) ---------- */
  function fillReceipt(root, d) {
    fillMap(root, receiptMap(d));
    var frows = buildFeeRows(feesFor(d.resort), parseDetail(d.feesDetail));
    renderReceiptFees(root, frows);
    setFeeCell(root, frows, d.feesDetail ? '' : addFeeText(String(d.additionalFees || '')));
  }
  function upMsg(msg, cls) { var m = $('upMsg'); m.textContent = msg; m.className = 'upmsg ' + (cls || ''); }
  function regenerate(i, btn) {
    var b = upcoming[i]; if (!b) return;
    btn.disabled = true; btn.textContent = 'Generating...'; upMsg('');
    var reset = function(){ btn.disabled = false; btn.textContent = 'Regenerate Receipt'; };
    RUN
      .withSuccessHandler(function(d){
        if (!d) { reset(); upMsg('Booking not found.', 'err'); return; }
        var root = document.createElement('div');
        root.className = 'receipt';
        mountReceipt(root, d.resort || DEFAULT_RESORT);
        fillReceipt(root, d);
        downloadImage(root, d.invoiceNo, d.name)
          .then(function(){ reset(); upMsg('Receipt for ' + d.invoiceNo + ' was downloaded.', 'ok'); })
          .catch(function(e){ reset(); upMsg('Could not create image: ' + e.message, 'err'); });
      })
      .withFailureHandler(function(e){ if (authFail(e)) return; reset(); upMsg('Could not load booking: ' + e.message, 'err'); })
      .getBooking(TOKEN, b.invoiceNo);
  }

  /* ---------- booking type (date + 5 options) ---------- */
  var TYPE_KEYS = ['day','overnight','morning22','evening22'];
  var TYPE_LABELS = {day:'Day Tour', overnight:'Overnight', morning22:'22 Hours (Morning slot)', evening22:'22 Hours (Evening slot)', custom:'Custom Date and Time'};
  var TYPE_COLORS = {day:'#5fcf6b', overnight:'#ffd43b', morning22:'#7cc9f0', evening22:'#1f3a8f', custom:'#a66ee0'};
  var TYPE_TEXT   = {day:'#0d2b12', overnight:'#3b2f00', morning22:'#0a2a3d', evening22:'#ffffff', custom:'#1d0b36'};
  // Times are loaded from the 'Booking Types' sheet (one set per resort); these are only the starting defaults.
  function defaultTimes() {
    return {
      day:       {inT:'08:00', outT:'17:00', days:0, enabled:true},
      overnight: {inT:'19:00', outT:'06:00', days:1, enabled:true},
      morning22: {inT:'08:00', outT:'06:00', days:1, enabled:true},
      evening22: {inT:'19:00', outT:'17:00', days:1, enabled:true}
    };
  }
  var BOOK_TYPES_ALL = {};
  function BT(resort) {
    var rs = resort || $('resort').value;
    return BOOK_TYPES_ALL[rs] || BOOK_TYPES_ALL[DEFAULT_RESORT] || (BOOK_TYPES_ALL[rs] = defaultTimes());
  }
  function pad2(n) { return ('0' + n).slice(-2); }
  function t12(hhmm) { var p = hhmm.split(':'), h = +p[0]; return (h % 12 || 12) + ':' + p[1] + ' ' + (h >= 12 ? 'PM' : 'AM'); }
  function typeHintText(k) {
    var c = BT()[k];
    return 'Check-in ' + t12(c.inT) + ', check-out ' + t12(c.outT) + (c.days ? ' the next day.' : ' the same day.');
  }
  function typeOptionsHtml(resort) {
    var html = '<option value="">Select a booking type...</option>', T = BT(resort);
    TYPE_KEYS.forEach(function(k){
      var c = T[k];
      if (c.enabled === false) return;
      html += '<option value="' + k + '">' + TYPE_LABELS[k] + ' (' + t12(c.inT) + ' to ' + t12(c.outT) + ')</option>';
    });
    return html + '<option value="custom">' + TYPE_LABELS.custom + '</option>';
  }
  function buildTypeOptions() {
    var cur = $('bookType').value;
    $('bookType').innerHTML = typeOptionsHtml($('resort').value); $('bookType').value = cur;
  }
  function loadBookingTypes() {
    if (!(window.google && google.script)) return;
    RUN.withSuccessHandler(function(t){
      if (t) Object.keys(t).forEach(function(rs){ TYPE_KEYS.forEach(function(k){ if (t[rs] && t[rs][k]) (BOOK_TYPES_ALL[rs] = BOOK_TYPES_ALL[rs] || defaultTimes())[k] = t[rs][k]; }); });
      buildTypeOptions();
      var k = $('bookType').value;
      if (BT()[k] && $('stayDate').value) $('typeHint').textContent = typeHintText(k) + (editing ? '' : ' Computed automatically.');
    }).getBookingTypes(TOKEN);
  }
  function addDays(ds, n) {
    var p = ds.split('-'), d = new Date(+p[0], +p[1] - 1, +p[2] + n);
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
  }
  // preserve = true keeps the saved check-in/out as they are (used when modifying an old booking)
  function applyBookType(preserve) {
    var t = $('bookType').value, d = $('stayDate').value, cfg = BT()[t], custom = (t === 'custom');
    ['checkIn','checkOut'].forEach(function(id){
      $(id).readOnly = !custom; $(id).classList.toggle('auto', !custom);
    });
    if (cfg) {
      if (!preserve) {
        if (d) { $('checkIn').value = d + 'T' + cfg.inT; $('checkOut').value = addDays(d, cfg.days) + 'T' + cfg.outT; }
        else { $('checkIn').value = ''; $('checkOut').value = ''; }
      }
      $('typeHint').textContent = d ? typeHintText(t) + (preserve ? '' : ' Computed automatically.') : 'Pick a date first.';
    } else if (custom) {
      var ci = $('checkIn').value, co = $('checkOut').value;
      if (!preserve) {
        if (d && !ci) { $('checkIn').value = d + 'T08:00'; $('checkOut').value = d + 'T17:00'; }
        else if (d && ci && ci.slice(0, 10) !== d && co) {      // date changed: move both dates together
          var diff = Math.round((Date.parse(d) - Date.parse(ci.slice(0, 10))) / 86400000);
          $('checkIn').value = d + 'T' + ci.slice(11);
          $('checkOut').value = addDays(co.slice(0, 10), diff) + 'T' + co.slice(11);
        }
      }
      $('typeHint').textContent = 'Choose the check-in and check-out date and time yourself.';
    } else {
      $('checkIn').value = ''; $('checkOut').value = '';
      $('typeHint').textContent = d ? 'Now choose a booking type.' : '';
    }
    update(); checkConflict();
  }
  // From saved check-in/out, work out which option it was (only used for older bookings with no saved type)
  function inferType(ci, co, resort, times) {
    if (!ci || !co) return {type:'', date:''};
    var date = ci.slice(0, 10), tm = ci.slice(11, 16), T = times || BT(resort);
    for (var i = 0; i < TYPE_KEYS.length; i++) {
      var k = TYPE_KEYS[i], c = T[k];
      if (c.inT === tm && co === addDays(date, c.days) + 'T' + c.outT) return {type:k, date:date};
    }
    return {type:'custom', date:date};
  }

  /* ---------- booking calendar ---------- */
  var calY = 0, calM = 0, calReq = 0, calModel = null;
  var MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  function pdate(str) {   // 'yyyy-MM-dd HH:mm'
    var m = str.match(/(\d+)-(\d+)-(\d+)[ T](\d+):(\d+)/);
    return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
  }
  function fmtC(d) {
    var h = d.getHours(), m = d.getMinutes();
    return (h % 12 || 12) + (m ? ':' + pad2(m) : '') + (h >= 12 ? 'p' : 'a');
  }
  function dstr(y, m, d) { var x = new Date(y, m, d); return x.getFullYear() + '-' + pad2(x.getMonth() + 1) + '-' + pad2(x.getDate()); }
  function fillKey() {
    $('calDayTxt').textContent = slotText('U'); $('calNightTxt').textContent = slotText('L');
    $('calKey').innerHTML = TYPE_KEYS.concat(['custom']).map(function(k){
      return '<span class="key"><i style="background:' + TYPE_COLORS[k] + '"></i>' + TYPE_LABELS[k] + '</span>';
    }).join('');
  }
  function openCalendar() {
    var d = $('stayDate').value ? new Date($('stayDate').value + 'T00:00:00') : new Date();
    calY = d.getFullYear(); calM = d.getMonth();
    $('calResort').value = $('resort').value;
    fillKey();
    $('calBg').style.display = 'flex';
    loadCalendar();
  }
  function calLogoSrc() { var r = RESORTS[$('calResort').value]; return r ? logoSrcOf(r) : ''; }
  function loadCalendar() {
    var req = ++calReq;
    var lg = calLogoSrc(), li = $('calLogo');
    if (lg) { li.src = lg; li.style.display = ''; } else { li.removeAttribute('src'); li.style.display = 'none'; }
    $('calTitle').textContent = MONTHS[calM] + ' ' + calY;
    $('calMsg').textContent = 'Loading...';
    var first = calY + '-' + pad2(calM + 1) + '-01';
    var last = calY + '-' + pad2(calM + 1) + '-' + pad2(new Date(calY, calM + 1, 0).getDate());
    RUN
      .withSuccessHandler(function(list){ if (req === calReq) { $('calMsg').textContent = ''; renderCalendar(list || []); } })
      .withFailureHandler(function(e){ if (authFail(e)) return; $('calMsg').textContent = 'Could not load the calendar: ' + e.message; })
      .getCalendarBookings(TOKEN, $('calResort').value, addDays(first, -2) + ' 00:00', addDays(last, 2) + ' 23:59');
  }
  // The two halves of a date box: 'U' = Day slot (the resort's Day Tour times), 'L' = Overnight slot
  function slotWin(ds, half, resort, times) {
    var T = times || BT(resort || $('calResort').value), c = half === 'U' ? T.day : T.overnight, p = ds.split('-').map(Number);
    var s = c.inT.split(':').map(Number), e = c.outT.split(':').map(Number);
    return [new Date(p[0], p[1] - 1, p[2], s[0], s[1]), new Date(p[0], p[1] - 1, p[2] + (c.days ? 1 : 0), e[0], e[1])];
  }
  function slotText(half, resort, times) {
    var T = times || BT(resort || $('calResort').value), c = half === 'U' ? T.day : T.overnight;
    return t12(c.inT).replace(':00', '').replace(' ', '') + '-' + t12(c.outT).replace(':00', '').replace(' ', '');
  }
  // Which half-days does a booking shade? 'U' = Day slot (upper), 'L' = Overnight slot (lower)
  function halvesFor(b, resort, times, rangeStart, rangeEnd) {
    var D = b.checkIn.slice(0, 10), out = [];
    if (b.type === 'day') out.push([D, 'U']);
    else if (b.type === 'overnight') out.push([D, 'L']);
    else if (b.type === 'morning22') { out.push([D, 'U']); out.push([D, 'L']); }
    else if (b.type === 'evening22') { out.push([D, 'L']); out.push([addDays(D, 1), 'U']); }
    else {
      var first = addDays(D, -1), last = addDays(b.e.getFullYear() + '-' + pad2(b.e.getMonth() + 1) + '-' + pad2(b.e.getDate()), 1);
      if (rangeStart && first < rangeStart) first = rangeStart;
      if (rangeEnd && last > rangeEnd) last = rangeEnd;
      for (var ds = first; ds <= last; ds = addDays(ds, 1)) {
        var u = slotWin(ds, 'U', resort, times), l = slotWin(ds, 'L', resort, times);
        if (b.s < u[1] && b.e > u[0]) out.push([ds, 'U']);
        if (b.s < l[1] && b.e > l[0]) out.push([ds, 'L']);
      }
    }
    return out;
  }
  function halfLabel(b, ds, half, both, resort, times) {
    var full = fmtC(b.s) + '-' + fmtC(b.e);               // the whole check-in to check-out time
    if (b.type !== 'custom' || both) return full;
    var w = slotWin(ds, half, resort, times), ss = w[0], se = w[1];
    return fmtC(b.s > ss ? b.s : ss) + '-' + fmtC(b.e < se ? b.e : se);
  }
  function buildCalModel(list, context) {
    context = context || { y:calY, m:calM, resort:$('calResort').value };
    var y = context.y, m = context.m, resort = context.resort, times = context.types || BT(resort);
    var rangeStart = dstr(y, m, 1), rangeEnd = dstr(y, m + 1, 0);
    var bks = list.map(function(b){
      var t = TYPE_COLORS[b.bookType] ? b.bookType : inferType(b.checkIn.replace(' ', 'T'), b.checkOut.replace(' ', 'T'), resort, times).type || 'custom';
      return {id:b.id, type:t, checkIn:b.checkIn, s:pdate(b.checkIn), e:pdate(b.checkOut)};
    });
    bks.sort(function(a, b){ return (a.s - b.s) || (a.id - b.id); });
    var map = {};
    var mp = y + '-' + pad2(m + 1) + '-', gn = 0;
    bks.forEach(function(b){
      var hs = halvesFor(b, resort, times, rangeStart, rangeEnd);
      // Guest numbers follow check-in order for the bookings shown in this month
      if (hs.some(function(h){ return h[0].indexOf(mp) === 0; })) b.guest = ++gn;
      hs.forEach(function(h){ (map[h[0] + '|' + h[1]] = map[h[0] + '|' + h[1]] || []).push(b); });
    });
    function half(hits, ds, h, both) {
      if (!hits || !hits.length) return null;
      var b = hits[0];
      var guest = hits.length > 1 ? 'Guests ' + hits.map(function(x){ return x.guest || '?'; }).join(' & ')
                                  : 'Guest ' + (b.guest || '?');
      return {c1: TYPE_COLORS[b.type], c2: hits.length > 1 ? TYPE_COLORS[hits[1].type] : null,
              txt: hits.length > 1 ? '#102a30' : TYPE_TEXT[b.type], label: halfLabel(b, ds, h, both, resort, times), guest: guest};
    }
    var cells = [], days = new Date(y, m + 1, 0).getDate();
    for (var d = 1; d <= days; d++) {
      var ds = dstr(y, m, d), U = map[ds + '|U'], L = map[ds + '|L'];
      var both = !!(U && L && U.length === 1 && L.length === 1 && U[0].id === L[0].id);
      cells.push({d:d, U:half(U, ds, 'U', both), L:half(L, ds, 'L', both), center: both ? halfLabel(U[0], ds, 'U', true, resort, times) : null, centerGuest: both ? 'Guest ' + (U[0].guest || '?') : null});
    }
    return {y:y, m:m, firstDow:new Date(y, m, 1).getDay(), days:days, cells:cells, resort:resort};
  }
  function bgOf(h, fallback) {
    if (!h) return fallback;
    return h.c2 ? 'repeating-linear-gradient(45deg,' + h.c1 + ' 0 6px,' + h.c2 + ' 6px 12px)' : h.c1;
  }
  function renderCalendar(list) {
    calModel = buildCalModel(list);
    $('calGrid').innerHTML = calendarHtml(calModel);
  }
  // Both login and authenticated calendars use exactly the same cells, colours and time-slot labels.
  function calendarHtml(model) {
    var now = new Date(), html = '';
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(function(w){ html += '<div class="cal-dow">' + w + '</div>'; });
    for (var i = 0; i < model.firstDow; i++) html += '<div class="cal-cell blank" aria-hidden="true"></div>';
    model.cells.forEach(function(c){
      var isToday = (now.getFullYear() === model.y && now.getMonth() === model.m && now.getDate() === c.d);
      var label = MONTHS[model.m] + ' ' + c.d + ', ' + model.y + '. Day: ' + (c.U ? c.U.guest + ' ' + c.U.label : 'Open') + '. Overnight: ' + (c.L ? c.L.guest + ' ' + c.L.label : 'Open');
      html += '<div class="cal-cell' + (isToday ? ' today' : '') + '" role="img" aria-label="' + esc(label) + '">' +
        '<div class="tri tri-day"' + (c.U ? ' style="background:' + bgOf(c.U) + '"' : '') + '></div>' +
        '<div class="tri tri-night"' + (c.L ? ' style="background:' + bgOf(c.L) + '"' : '') + '></div>' +
        '<div class="diag"></div><span class="cnum"' + (c.U ? ' style="color:' + c.U.txt + ';text-shadow:none"' : '') + '>' + c.d + '</span>' +
        (c.center ? '<span class="ct ccenter"><b>' + c.centerGuest + '</b>' + c.center + '</span>' :
          ((c.U ? '<span class="ct cday" style="color:' + c.U.txt + ';text-shadow:none"><b>' + c.U.guest + '</b>' + c.U.label + '</span>' : '') +
           (c.L ? '<span class="ct cnight" style="color:' + c.L.txt + ';text-shadow:none"><b>' + c.L.guest + '</b>' + c.L.label + '</span>' : ''))) +
        '</div>';
    });
    return html;
  }
  function calMove(n) { calM += n; if (calM < 0) { calM = 11; calY--; } if (calM > 11) { calM = 0; calY++; } loadCalendar(); }

  // Draw the month onto a canvas and download it as a PNG (no guest details are drawn)
  // the resort logo is drawn once it has loaded; without a logo the image is drawn at once
  function withLogo(src, cb) {
    if (!src) { cb(null); return; }
    var img = new Image(); img.onload = function(){ cb(img); }; img.onerror = function(){ cb(null); }; img.src = src;
  }
  function drawLogo(g, img, right, top, box) {
    if (!img || !img.width) return;
    var sc = Math.min(box / img.width, box / img.height), w = img.width * sc, h = img.height * sc;
    g.drawImage(img, right - w, top + (box - h) / 2, w, h);
  }
  function downloadCalendarImage() {
    if (!calModel) { $('calMsg').textContent = 'The calendar is still loading.'; return; }
    var model = calModel; withLogo(calLogoSrc(), function(logo){drawCalendarImage(logo,model);});
  }
  function drawCalendarImage(logoImg, model) {
    var M = model || calModel, SC = 2, W = 1000, pad = 28, gap = 5;
    var cw = Math.floor((W - pad * 2 - gap * 6) / 7), ch = Math.round(cw * 0.9);
    var rows = Math.ceil((M.firstDow + M.days) / 7);
    var headH = 92, dowH = 28, legendH = 120;
    var H = headH + dowH + rows * (ch + gap) + legendH + pad;
    var cv = document.createElement('canvas'); cv.width = W * SC; cv.height = H * SC;
    var g = cv.getContext('2d'); g.scale(SC, SC);
    g.fillStyle = '#ffffff'; g.fillRect(0, 0, W, H);
    var F = 'Inter, Arial, sans-serif';
    g.fillStyle = '#17333a'; g.font = '800 28px ' + F; g.textAlign = 'left'; g.textBaseline = 'alphabetic';
    g.fillText('Booking Calendar', pad, 46);
    g.font = '600 19px ' + F; g.fillStyle = '#0b7f8d';
    g.fillText(M.resort + '  |  ' + MONTHS[M.m] + ' ' + M.y, pad, 76);
    drawLogo(g, logoImg, W - pad, 14, 66);
    g.textAlign = 'center'; g.font = '700 13px ' + F; g.fillStyle = '#5b6f75';
    ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(function(w, i){ g.fillText(w, pad + i * (cw + gap) + cw / 2, headH + 18); });
    function tri(x, y, w, h, half) {
      g.beginPath();
      if (half === 'U') { g.moveTo(x, y); g.lineTo(x + w, y); g.lineTo(x, y + h); }
      else { g.moveTo(x + w, y); g.lineTo(x + w, y + h); g.lineTo(x, y + h); }
      g.closePath();
    }
    function paint(x, y, w, h, half, spec, base) {
      tri(x, y, w, h, half); g.fillStyle = spec ? spec.c1 : base; g.fill();
      if (spec && spec.c2) {
        g.save(); tri(x, y, w, h, half); g.clip(); g.strokeStyle = spec.c2; g.lineWidth = 6;
        for (var k = -h; k < w + h; k += 12) { g.beginPath(); g.moveTo(x + k, y + h); g.lineTo(x + k + h, y); g.stroke(); }
        g.restore();
      }
    }
    M.cells.forEach(function(c, i){
      var pos = M.firstDow + i, col = pos % 7, row = Math.floor(pos / 7);
      var x = pad + col * (cw + gap), y = headH + dowH + row * (ch + gap);
      paint(x, y, cw, ch, 'U', c.U, '#f6fafb'); paint(x, y, cw, ch, 'L', c.L, '#eceff3');
      g.strokeStyle = '#7d8d92'; g.lineWidth = 1; g.beginPath(); g.moveTo(x, y + ch); g.lineTo(x + cw, y); g.stroke();
      g.strokeStyle = '#b9c6c9'; g.strokeRect(x + .5, y + .5, cw - 1, ch - 1);
      g.textAlign = 'left'; g.font = '800 15px ' + F; g.fillStyle = c.U ? c.U.txt : '#17333a'; g.fillText(String(c.d), x + 7, y + 20);
      g.font = '700 13px ' + F;
      if (c.center) {
        var tw = Math.max(g.measureText(c.center).width, g.measureText(c.centerGuest).width);
        g.fillStyle = 'rgba(255,255,255,.88)'; g.fillRect(x + cw / 2 - tw / 2 - 5, y + ch / 2 - 18, tw + 10, 36);
        g.fillStyle = '#102a30'; g.textAlign = 'center';
        g.fillText(c.centerGuest, x + cw / 2, y + ch / 2 - 3); g.fillText(c.center, x + cw / 2, y + ch / 2 + 13);
      } else {
        if (c.U) { g.fillStyle = c.U.txt; g.textAlign = 'left'; g.fillText(c.U.guest, x + 7, y + 38); g.fillText(c.U.label, x + 7, y + 54); }
        if (c.L) { g.fillStyle = c.L.txt; g.textAlign = 'right'; g.fillText(c.L.label, x + cw - 7, y + ch - 9); g.fillText(c.L.guest, x + cw - 7, y + ch - 25); }
      }
    });
    // legend
    var ly = headH + dowH + rows * (ch + gap) + 22, lx = pad;
    g.textAlign = 'left'; g.font = '700 13px ' + F;
    TYPE_KEYS.concat(['custom']).forEach(function(k){
      g.fillStyle = TYPE_COLORS[k]; g.fillRect(lx, ly - 12, 16, 16);
      g.strokeStyle = 'rgba(0,0,0,.3)'; g.strokeRect(lx + .5, ly - 11.5, 15, 15);
      g.fillStyle = '#17333a'; g.fillText(TYPE_LABELS[k], lx + 22, ly);
      lx += 22 + g.measureText(TYPE_LABELS[k]).width + 18;
    });
    g.font = '500 12.5px ' + F; g.fillStyle = '#5b6f75';
    g.fillText('Each date box is split in two: upper-left = Day slot (' + slotText('U', M.resort, M.types) + '), lower-right = Overnight slot (' + slotText('L', M.resort, M.types) + ').', pad, ly + 30);
    g.fillText('A shaded part is booked. Blank parts are available. Striped parts mean two bookings overlap. Guest numbers follow check-in order for the month.', pad, ly + 50);
    var a = document.createElement('a');
    a.download = 'Calendar_' + M.resort.replace(/[^a-z0-9]+/gi, '-') + '_' + M.y + '-' + pad2(M.m + 1) + '.png';
    a.href = cv.toDataURL('image/png');
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  }

  function validate() {
    var missing = [];
    var L = RC().labels;
    if (RC().invoiceMode === 'Manual' && !$('invoiceNo').value.trim()) missing.push(L.invoiceNo);
    if (!$('name').value.trim()) missing.push('Guest Name');
    if (!$('contact').value.trim()) missing.push('Contact #');
    if ($('bookingFee').value === '') missing.push(L.bookingFee);
    if (referredVal() === 'Yes') {
      if (!$('marketer').value.trim()) missing.push('Agent name');
      if (pctVal() === '' || !(pctVal() >= 0 && pctVal() <= 100)) missing.push('Agent percentage (0 to 100)');
    }
    if (!$('stayDate').value) missing.push('Reservation Date');
    if (!$('bookType').value) missing.push('Booking Type');
    else if ($('bookType').value === 'custom') {
      if (!$('checkIn').value) missing.push(L.checkIn);
      if (!$('checkOut').value) missing.push(L.checkOut);
    }
    if ($('checkIn').value && $('checkOut').value && $('checkOut').value <= $('checkIn').value) missing.push('a ' + L.checkOut + ' later than the ' + L.checkIn);
    return missing;
  }
  function collectData(isUpdate) {
    update();
    var data = {
      resort: $('resort').value, bookType: $('bookType').value,
      invoiceNo: $('invoiceNo').value, name: $('name').value, contact: $('contact').value,
      address: $('address').value, dpDate: $('dpDate').value, bookingDate: $('dpDate').value,
      bookingFee: $('bookingFee').value, downPayment: $('downPayment').value, balance: $('balance').value,
      mode: $('mode').value, checkIn: $('checkIn').value.replace('T',' '), checkOut: $('checkOut').value.replace('T',' '),
      pax: $('pax').value, additionalFees: $('additionalFees').value, marketer: agentNameVal(),
      referred: referredVal(), agentPct: referredVal() === 'Yes' ? pctVal() : '', agentPay: agentPayVal(),
      feesDetail: $('feesDetail').value, feesTotal: feesTotal(domRows()),
      notes: $('notes').value, proof: proofData, isUpdate: isUpdate,
      roomsIncluded:$('roomsIncluded').value,extraField1:$('extraField1').value,extraField2:$('extraField2').value,extraField3:$('extraField3').value
    };
    if (editing && editing.financialLocked && editing.financial) Object.keys(editing.financial).forEach(function(key){data[key]=editing.financial[key];});
    return data;
  }

  function saveFlow(withReceipt) {
    if (saving) return;
    var missing = validate();
    if (missing.length) { setStatus('Please fill in: ' + missing.join(', '), 'err'); return; }

    saving = true; $('btnDownload').disabled = true; $('btnSaveRecord').disabled = true; setStatus('Saving to sheet...');
    var session = TOKEN, data = collectData($('invoiceNo').value.trim() === savedInvoice && savedInvoice !== '');
    var done = function(msg, cls){ if (TOKEN !== session) return; saving = false; $('btnDownload').disabled = false; $('btnSaveRecord').disabled = false; setStatus(msg, cls); };

    RUN
      .withSuccessHandler(function(res){
        if (TOKEN !== session) return;
        var previousInvoice = $('invoiceNo').value;
        savedInvoice = res.invoiceNo;
        if ($('invoiceNo').value !== res.invoiceNo) { $('invoiceNo').value = res.invoiceNo; update(); }
        if (res.renamed) {
          var old = previousInvoice;
          $('invoiceNo').value = res.invoiceNo; update();
          showInvNotice('Invoice No. ' + old + ' already exists. A new random invoice number (' + res.invoiceNo + ') was generated and used.');
        }
        if (res.refresh) applyBookingRefresh(res.refresh);
        else { dashLoadedAt = 0; loadUpcoming(); loadMarketers(); }
        var inv = res.invoiceNo, extra = res.renamed ? ' (the invoice number you entered already existed, so ' + inv + ' was used)' : '';
        // after a successful save the form goes back to a fresh booking
        var finish = function(msg){ if (TOKEN !== session) return; saving = false; $('btnDownload').disabled = false; $('btnSaveRecord').disabled = false; newBooking(); setStatus(msg, 'ok'); };
        if (!withReceipt) { finish((res.updated ? 'Booking ' + inv + ' was updated in the sheet.' : 'Booking ' + inv + ' was saved to the sheet.') + extra + ' No receipt was downloaded. The form is ready for a new booking.'); return; }
        setStatus('Saved. Creating receipt...');
        downloadImage()
          .then(function(){ finish((res.updated ? 'Booking ' + inv + ' was updated' : 'Booking ' + inv + ' was saved') + ' and the receipt was downloaded.' + extra + ' The form is ready for a new booking.'); })
          .catch(function(e){ done('Saved, but the receipt failed: ' + e.message + ' You can press Save & Download Receipt again.', 'err'); });
      })
      .withFailureHandler(function(e){ if (TOKEN !== session || authFail(e)) return; done('Could not save: ' + e.message, 'err'); })
      .saveBooking(TOKEN, data, true);
  }

  /* ---------- marketer autocomplete ---------- */
  var marketers = [];
