        $('resort').value = d.resort || DEFAULT_RESORT;
        applyResortUI(); mountReceipt($('receipt'), $('resort').value);
        if (d.mode && ![].some.call($('mode').options, function(o){ return o.value === d.mode; })) $('mode').insertAdjacentHTML('beforeend', '<option>' + esc(d.mode) + '</option>');
        FIELDS.forEach(function(f){ if (d[f] !== undefined) $(f).value = d[f]; });
        if (!$('dpDate').value) $('dpDate').value = d.bookingDate || '';
        renderFeeList(feesFor(d.resort), parseDetail(d.feesDetail));
        setReferred(d.referred === 'Yes' ? 'Yes' : 'No'); setPct(d.agentPct === '' ? CFG.settings.agentDefault : d.agentPct);
        clearProof(); toggleProof(); showInvNotice('');
        $('invoiceNo').readOnly = true;
