  function reviewChanges() {
    if (!editing || saving) return;
    var missing = validate();
    if (missing.length) { setStatus('Please fill in: ' + missing.join(', '), 'err'); return; }
    var now = snapshot(), rows = [];
    DIFF_FIELDS.forEach(function(f){
      var k = f[0];
      if (!same(k, editing.original[k], now[k])) {
        rows.push('<tr><td class="lbl">' + esc(labelFor(f[0], f[1])) + '</td><td class="from">' + esc(showVal(k, editing.original[k])) +
                  '</td><td class="to">' + esc(showVal(k, now[k])) + '</td></tr>');
      }
    });
    if (proofData) rows.push('<tr><td class="lbl">Payment receipt</td><td class="from">(previous kept in Drive)</td><td class="to">New screenshot attached</td></tr>');
    if (!rows.length) { setStatus('No changes were made.', 'err'); return; }
    setStatus('');
    $('editSub').textContent = 'Booking ' + editing.invoiceNo + ': ' + rows.length + ' change' + (rows.length > 1 ? 's' : '') + ' to be saved.';
    $('diffBody').innerHTML = rows.join('');
    $('editBg').style.display = 'flex';
  }
  function setEditBusy(b) {
    ['btnSaveGen','btnSaveOnly','btnBackEdit'].forEach(function(id){ $(id).disabled = b; });
  }
  function commitEdit(generate) {
    if (saving) return;
    saving = true; setEditBusy(true); setStatus('Saving changes...');
    var session = TOKEN, inv = editing.invoiceNo;
    var finish = function(msg, cls, reset) {
      if (TOKEN !== session) return;
      saving = false; setEditBusy(false); $('editBg').style.display = 'none';
      if (reset) { newBooking(); showScreen('menu'); menuNote(msg); }
      else setStatus(msg, cls);
    };
    RUN
      .withSuccessHandler(function(res){
        if (TOKEN !== session) return;
        if (res.refresh) applyBookingRefresh(res.refresh);
        else { dashLoadedAt = 0; loadUpcoming(); loadMarketers(); }
        if (!generate) { finish('Changes to ' + inv + ' were saved.', 'ok', true); return; }
        setStatus('Saved. Creating new confirmation image...');
        downloadImage()
          .then(function(){ finish('Changes to ' + inv + ' were saved and the new confirmation image was downloaded.', 'ok', true); })
          .catch(function(e){ finish('Saved, but image failed: ' + e.message, 'err', false); });
      })
      .withFailureHandler(function(e){ if (TOKEN !== session || authFail(e)) return; finish('Could not save: ' + e.message, 'err', false); })
      .saveBooking(TOKEN, collectData(true), true);
  }

