  function numOrNull(n) { return (typeof n === 'number' && isFinite(n)) ? n : null; }      // an empty box must not be sent as NaN
  function ownVal() { var r = document.querySelector('input[name=reOwn]:checked'); return r ? r.value : 'Owned'; }
