  // shrink a chosen picture in the browser before sending it
  function readPicture(file, kind, cb, messageId) {
    var rd = new FileReader();
    rd.onload = function(e){
      var img = new Image();
      img.onload = function(){
        var max = kind === 'logo' ? 360 : 900, sc = Math.min(1, max / Math.max(img.width, img.height));
        var c = document.createElement('canvas'); c.width = Math.round(img.width * sc); c.height = Math.round(img.height * sc);
        var g = c.getContext('2d'), out;
        if (kind === 'logo') {
          g.drawImage(img, 0, 0, c.width, c.height);
          out = c.toDataURL('image/png');
          if (out.length > 150000) { g.globalCompositeOperation = 'destination-over'; g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); out = c.toDataURL('image/jpeg', .85); }
        } else {      // background photo: washed out so the text on top stays easy to read
          g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);
          g.fillStyle = 'rgba(255,255,255,.8)'; g.fillRect(0, 0, c.width, c.height);
          out = c.toDataURL('image/jpeg', .72);
        }
        cb(out);
      };
      img.onerror = function(){ admMsg(messageId || 'resEdMsg', 'Could not read that picture.', 'err'); };
      img.src = e.target.result;
    };
    rd.onerror = function(){ admMsg(messageId || 'resEdMsg', 'Could not read that picture.', 'err'); };
    rd.readAsDataURL(file);
  }
  function saveResortEditor() {
    var o = editorCfg();
    if (!o.name) { admMsg('resEdMsg', 'Please enter the resort name.', 'err'); return; }
    if (o.ownership === 'Rented') {
      if (!(o.rentTotal > 0)) { admMsg('resEdMsg', 'This resort is rented: please enter the total rent amount.', 'err'); $('re_rentTotal').focus(); return; }
      if (!(o.rentTermValue >= 1)) { admMsg('resEdMsg', 'This resort is rented: please enter the term length, for example 5 months or 2 years.', 'err'); $('re_termVal').focus(); return; }
    }
    setBusy($('btnResSave'), true, 'Saving...'); admMsg('resEdMsg', '');
    var fail = function(e){ setBusy($('btnResSave'), false); if (admFail(e)) return; admMsg('resEdMsg', 'Could not save: ' + (e.message || e), 'err'); };
    RUN
      .withSuccessHandler(function(r){
        if (!r.ok) { setBusy($('btnResSave'), false); admMsg('resEdMsg', r.message, 'err'); return; }
        // then the pictures, one after the other
        var jobs = [];
        ['logo', 'bg'].forEach(function(k){
          var st = resEd[k];
          if (st.pending) jobs.push(function(next){ RUN.withSuccessHandler(next).withFailureHandler(fail).saveResortImage(TOKEN, ADMIN_TOKEN, o.name, k, st.pending); });
          else if (st.remove) jobs.push(function(next){ RUN.withSuccessHandler(next).withFailureHandler(fail).removeResortImage(TOKEN, ADMIN_TOKEN, o.name, k); });
        });
        (function run(i){
          if (i >= jobs.length) {
            setBusy($('btnResSave'), false); $('resEdBg').style.display = 'none';
            loadAdmin(); admMsg('resMsg', 'Saved "' + o.name + '".', 'ok'); return;
          }
          jobs[i](function(res){ if (res && res.ok === false) { setBusy($('btnResSave'), false); admMsg('resEdMsg', res.message, 'err'); return; } run(i + 1); });
        })(0);
      })
      .withFailureHandler(fail)
      .saveResort(TOKEN, ADMIN_TOKEN, resEd.orig, o);
  }
  // ----- receipt preview with the settings in the editor -----
  function previewReceiptCfg(cfg) {
    var root = document.createElement('div'); root.className = 'receipt';
    var logoSt = resEd.logo, bgSt = resEd.bg;
    cfg.logo = logoSt.remove ? '' : (logoSt.pending || logoSt.cur);
    cfg.bg = bgSt.remove ? '' : (bgSt.pending || bgSt.cur);
    var shown = {};
    for (var k in cfg) shown[k] = cfg[k];
    // BUILTIN images are matched by name, so give the preview its pictures directly
    shown.name = cfg.name || 'Sample Resort';
    mountReceiptCfg(root, shown);
    var t = new Date(), iso = t.getFullYear() + '-' + pad2(t.getMonth() + 1) + '-' + pad2(t.getDate());
    var d = addDays(iso, 14);
    fillMap(root, receiptMap({name:'Juan Dela Cruz', contact:'0917 123 4567', address:'Quezon City', invoiceNo:(CFG.settings.invoicePrefix || 'INV#') + t.getFullYear() + '-00001',
      dpDate:iso, bookingFee:5000, downPayment:1500, balance:3500, mode:'GCash', checkIn:d + 'T08:00', checkOut:d + 'T17:00', pax:8, marketer:'Ana',roomsIncluded:'Rooms 1 and 2',extraField1:'Sample detail',extraField2:'',extraField3:''}));
    var rows = [{name:'Extra item', p:300, d:'per item', q:1, on:true}, {name:'Another item', p:500, d:'', q:1, on:false}];
    renderReceiptFees(root, rows); setFeeCell(root, rows, '');
    return root;
  }
  function showPreview() {
    var cfg = editorCfg();
    if (!cfg.name) cfg.name = 'Sample Resort';
    var root = previewReceiptCfg(cfg);
    $('prevScaler').innerHTML = ''; $('prevScaler').appendChild(root);
    $('prevBg').style.display = 'flex';
    var w = $('prevWrap').clientWidth || 700, s = Math.min(1, w / 800);
    $('prevScaler').style.transform = 'scale(' + s + ')';
    $('prevWrap').style.height = (root.offsetHeight * s) + 'px';
  }

  /* ---------- financial report ---------- */
  var repReq = 0, repData = null, repYearsFilled = false, repLoadedFilters = null;
  function fillMonthSelect() {
    var h = '', n = new Date().getMonth();
    MONTHS.forEach(function(m, i){ h += '<option value="' + (i + 1) + '"' + (i === n ? ' selected' : '') + '>' + m + '</option>'; });
    $('repMonth').innerHTML = h;
  }
  function repMode() { return document.querySelector('input[name=repMode]:checked').value; }
  function openReport() {
    if (!$('repMonth').innerHTML) fillMonthSelect();
    showScreen('report');
    loadReport();
  }
  var REP_VIEWS = {all:'Income, expenses and return of investment', ie:'Income and expenses', inc:'Income only', exp:'Expenses only', roi:'Return of investment only'};
  function repFilters() {
    return {resort:$('repResort').value, mode:repMode(), year:$('repYear').value, month:$('repMonth').value, from:$('repFrom').value,to:$('repTo').value,basis:$('repBasis').value, view:$('repView').value};
  }
  function syncRepView() { $('repBasisWrap').style.display = $('repView').value === 'roi' ? 'none' : ''; }
  function loadReport() {
    var req = ++repReq, mode = repMode();
    $('repMonthWrap').style.display = mode === 'month' ? '' : 'none';
    $('repYearWrap').style.display = mode === 'range' ? 'none' : ''; $('repRangeWrap').hidden = mode !== 'range';
    if (!$('repFrom').value) $('repFrom').value = dstr(new Date().getFullYear(),new Date().getMonth(),1);
    if (!$('repTo').value) $('repTo').value = todayIso();
    repData = null; repLoadedFilters = null; $('btnRepDl').disabled = true;
    if (mode === 'range' && (!$('repFrom').value || !$('repTo').value || $('repFrom').value > $('repTo').value)) { $('repMsg').textContent = 'Choose valid start and end dates, then Apply dates.'; return; }
    syncRepView();
    var year = $('repYear').value || String(new Date().getFullYear());
    var filters = repFilters(); filters.year = year; filters.month = filters.month || String(new Date().getMonth()+1);
    $('repMsg').textContent = 'Building the report...';
    RUN
      .withSuccessHandler(function(d){
        if (req !== repReq) return;
        $('repMsg').textContent = '';
        if (!repYearsFilled || $('repYear').options.length !== d.years.length) {
          var cur = $('repYear').value || year;
          $('repYear').innerHTML = d.years.map(function(y){ return '<option>' + y + '</option>'; }).join('');
          $('repYear').value = d.years.indexOf(cur) > -1 ? cur : d.years[0];
          repYearsFilled = true;
        }
        repData = d; repLoadedFilters = filters; renderReport(d, filters); $('btnRepDl').disabled = false;
      })
      .withFailureHandler(function(e){ if (authFail(e)) return; $('repMsg').textContent = 'Could not build the report: ' + e.message; })
      .getReportData(TOKEN, filters.resort, mode, year, filters.month, filters.basis, filters.from, filters.to);
  }
  function pesoE(v) { return esc(peso(v || 0)); }
  function emptyRow(cols, text) { return '<tr><td colspan="' + cols + '" style="color:#5b6f75">' + text + '</td></tr>'; }

  /* return of investment of the rented resorts (always "from the rent start date until today", whatever period is chosen) */
  function roiHTML(d, f) {
    var h = '<div class="rsec"><h4>Return of investment (rented resorts)</h4>', list = d.roi || [];
    if (!list.length) {
      h += '<div class="rnote2">' + (f.resort
        ? esc(f.resort) + ' is not marked as rented, so there is no rent to recover. To track a return of investment, edit the resort in Admin Settings and choose "Rented from another owner".'
        : 'No resort is marked as rented yet. In Admin Settings, edit a resort and choose "Rented from another owner" to see here whether its rent has been recovered.') + '</div></div>';
      return h;
    }
    list.forEach(function(x){
      var pct = Math.max(0, Math.min(100, x.recoveredPct));
      var stateTxt = x.state === 'notstarted' ? ' (the rent period has not started yet)' : (x.state === 'ended' ? ' (the rent term has ended)' : '');
      h += '<div class="roi-card ' + (x.recovered ? 'ok' : 'no') + '">' +
        '<h5>' + esc(x.resort) + ' <span class="badge ' + (x.recovered ? 'paid' : 'pending') + '">' + (x.recovered ? 'Investment recovered' : 'Not yet recovered') + '</span></h5>' +
        '<div class="roi-msg">' + (x.recovered
          ? 'Net income so far is ' + pesoE(x.surplus) + ' above the total rent of ' + pesoE(x.rentTotal) + ', a return of investment of ' + x.roiPct + '%.'
          : pesoE(x.remaining) + ' more net income is needed to cover the total rent of ' + pesoE(x.rentTotal) + '.') + '</div>' +
        '<div style="font-size:12px;font-weight:600;margin-bottom:3px">Rent recovered: ' + x.recoveredPct + '%</div>' +
        '<div class="bar big"><i class="' + (x.recovered ? '' : 'warn') + '" style="width:' + pct + '%"></i></div>';
      if (x.start) {
        h += '<div style="font-size:12px;font-weight:600;margin:10px 0 3px">Rent term used: ' + x.elapsedPct + '%</div>' +
             '<div class="bar big"><i class="term" style="width:' + Math.max(0, Math.min(100, x.elapsedPct)) + '%"></i></div>';
      }
      h += '<table class="rt" style="margin-top:10px">' +
        '<tr><td>Total rent and term</td><td class="r">' + pesoE(x.rentTotal) + ' for ' + esc(x.termLabel) + '</td></tr>' +
        '<tr><td>Rent period</td><td class="r">' + (x.start ? esc(fmtDate(x.start)) + ' to ' + esc(fmtDate(x.end)) + esc(stateTxt) : 'No start date set, so every record is counted') + '</td></tr>' +
        '<tr><td>Income to date (' + x.bookings + ' booking' + (x.bookings === 1 ? '' : 's') + ' already started)</td><td class="r">' + pesoE(x.income) + '</td></tr>' +
        '<tr><td>Agent pay</td><td class="r">' + pesoE(x.agentPay) + '</td></tr>' +
        '<tr><td>Other expenses paid</td><td class="r">' + pesoE(x.expenses) + '</td></tr>' +
        '<tr class="tot"><td>Net income to date</td><td class="r">' + pesoE(x.net) + '</td></tr></table></div>';
    });
    return h + '</div>';
  }

  function renderReport(d, f) {
    var T = d.totals, pesoN = pesoE;
    var V = f.view || 'all';
    var showInc = V === 'all' || V === 'ie' || V === 'inc';
    var showExp = V === 'all' || V === 'ie' || V === 'exp';
    var showRoi = V === 'all' || V === 'roi';
    var showNet = showInc && showExp, showPeriod = showInc || showExp;
    var period = f.mode === 'range' ? f.from + ' to ' + f.to : (f.mode === 'month' ? MONTHS[f.month - 1] + ' ' : '') + f.year;
    var rows = f.mode === 'range' ? (d.trend || []) : (f.mode === 'year' ? d.byMonth : d.byWeek);
    function kpi(cls, l, v, sub) { return '<div class="kpi ' + cls + '"><div class="l">' + l + '</div><div class="v">' + v + '</div>' + (sub ? '<div class="s">' + sub + '</div>' : '') + '</div>'; }
    function pair(blocks) {      // two blocks side by side, a last single block takes the full width
      blocks = blocks.filter(Boolean);
      var out = '';
      for (var i = 0; i < blocks.length; i += 2) {
        out += blocks[i + 1] ? '<div class="rsec cols2"><div>' + blocks[i] + '</div><div>' + blocks[i + 1] + '</div></div>' : '<div class="rsec">' + blocks[i] + '</div>';
      }
      return out;
    }
    var sub = [esc(f.resort || 'All Resorts')];
    if (showPeriod) sub.push(esc(period));
    if (showPeriod) sub.push('bookings by ' + (f.basis === 'booking' ? 'down payment date' : 'check-in date'));
    if (showExp) sub.push('expenses by date paid');
    if (showRoi && !showPeriod) sub.push('from the rent start date until today');
    sub.push(esc(REP_VIEWS[V] || ''));
    var logos = f.resort ? [RESORTS[f.resort]] : CFG.resorts;
    var sources = !f.resort && logos.length > 1 && CFG.businessLogo ? [CFG.businessLogo] : logos.filter(Boolean).map(logoSrcOf).filter(Boolean);
    var rpLogo = sources.map(function(src){ return '<img class="rp-logo" src="' + attr(src) + '" alt="">'; }).join('');
    var h = '<div class="rp-h"><div class="ttl">' + rpLogo + '<div><h3>Financial Report</h3><div class="sub">' + sub.join(' &middot; ') + '</div></div></div>' +
            '<div class="gen">Generated ' + esc(new Date().toLocaleString('en-US', {month:'short', day:'numeric', year:'numeric', hour:'numeric', minute:'2-digit'})) + '</div></div>';

    // ---- key numbers ----
    var k = '';
    if (showInc) k += kpi('inc', 'Total income (billed)', pesoN(T.billed), 'Booking fees ' + pesoN(T.bookingFees) + ' + additional fees ' + pesoN(T.addFees) + (T.extraCharges ? ' + extra charges ' + pesoN(T.extraCharges) : ''));
    if (showExp) k += kpi('exp', 'Total expenses', pesoN(T.totalCosts), 'Agent pay ' + pesoN(T.agentPay) + ' + other expenses ' + pesoN(T.expenses) + (showInc ? ' &middot; ' + T.costPct + '% of income' : ''));
    if (showNet) k += kpi('net', 'Net income', pesoN(T.net), 'Income minus agent pay and other expenses');
    if (showInc) {
      k += kpi('', 'Bookings', String(T.bookings), T.pax + ' guests &middot; avg ' + T.avgPax + ' per booking') +
           kpi('', 'Average booking value', pesoN(T.avgBooking), 'Referral share ' + T.referralShare + '% of bookings') +
           kpi('caution', 'Balance still to collect', pesoN(T.pendingUpcoming), 'On upcoming bookings. Down payments received: ' + pesoN(T.downPayments));
    }
    if (showExp) {
      k += kpi('', 'Agent pay', pesoN(T.agentPay), T.referred + ' referred booking' + (T.referred === 1 ? '' : 's') + ' &middot; ' + T.agentCostPct + '% of income') +
           kpi('', 'Other expenses recorded', pesoN(T.expenses), T.expCount + ' record' + (T.expCount === 1 ? '' : 's') + ' &middot; Products ' + pesoN(T.expProduct) + ' &middot; Services ' + pesoN(T.expService));
    }
    if (k) h += '<div class="kpis">' + k + '</div>';

    // ---- trend ----
    if (showPeriod) {
      var cols = [];
      if (showInc) { cols.push({h:'Bookings', f:function(r){ return r.count; }, t:T.bookings}); cols.push({h:'Income', f:function(r){ return pesoN(r.billed); }, t:pesoN(T.billed)}); }
      if (showExp) { cols.push({h:'Agent pay', f:function(r){ return pesoN(r.agentPay); }, t:pesoN(T.agentPay)}); cols.push({h:'Other expenses', f:function(r){ return pesoN(r.expenses); }, t:pesoN(T.expenses)}); }
      if (showExp && !showInc) cols.push({h:'Total expenses', f:function(r){ return pesoN(r.agentPay + r.expenses); }, t:pesoN(T.totalCosts)});
      if (showNet) cols.push({h:'Net', f:function(r){ return pesoN(r.billed - r.agentPay - r.expenses); }, t:pesoN(T.net)});
      var barOf = showInc ? function(r){ return r.billed; } : function(r){ return r.agentPay + r.expenses; };
      var maxB = 0; rows.forEach(function(r){ if (barOf(r) > maxB) maxB = barOf(r); });
      h += '<div class="rsec"><h4>' + (f.mode === 'month' ? 'Weekly trend' : 'Monthly trend') + '</h4><table class="rt"><tr><th>' + (f.mode === 'month' ? 'Days' : 'Month') + '</th>' +
           cols.map(function(c){ return '<th class="r">' + c.h + '</th>'; }).join('') + '<th style="width:22%">' + (showInc ? 'Income' : 'Expenses') + '</th></tr>';
      rows.forEach(function(r, i){
        var label = f.mode === 'range' ? r.label : f.mode === 'year' ? MONTHS[i].slice(0, 3) : 'Day ' + r.label;
        if (f.mode === 'month' && i === 4 && !r.count && !r.expenses) return;
        h += '<tr><td>' + label + '</td>' + cols.map(function(c){ return '<td class="r">' + c.f(r) + '</td>'; }).join('') +
             '<td><div class="bar"><i class="' + (showInc ? '' : 'pay') + '" style="width:' + (maxB ? Math.round(barOf(r) * 100 / maxB) : 0) + '%"></i></div></td></tr>';
      });
      h += '<tr class="tot"><td>Total</td>' + cols.map(function(c){ return '<td class="r">' + c.t + '</td>'; }).join('') + '<td></td></tr></table></div>';
    }

    // ---- agent ranking (agent pay is an expense) ----
    if (showExp) {
      h += '<div class="rsec"><h4>Agent ranking (by referrals)</h4>';
      if (!d.agents.length) h += '<div style="color:#5b6f75;font-size:13px">No agent referrals in this period.</div>';
      else {
        h += '<table class="rt"><tr><th>Rank</th><th>Agent</th><th class="r">Referrals</th><th class="r">Booking fees referred</th><th class="r">Avg %</th><th class="r">Agent pay</th></tr>';
        d.agents.forEach(function(a, i){
          h += '<tr><td><span class="medal' + (i < 3 ? ' m' + (i + 1) : '') + '">' + (i + 1) + '</span></td><td><b>' + esc(a.name) + '</b></td><td class="r">' + a.count +
               '</td><td class="r">' + pesoN(a.fees) + '</td><td class="r">' + (a.avgPct === '' ? '-' : a.avgPct + '%') + '</td><td class="r">' + pesoN(a.pay) + '</td></tr>';
        });
        h += '<tr class="tot"><td></td><td>Total</td><td class="r">' + T.referred + '</td><td></td><td></td><td class="r">' + pesoN(T.agentPay) + '</td></tr></table>';
      }
      h += '</div>';
    }

    // ---- income blocks ----
    var bResort = '';
    if (!f.resort && showPeriod) {
      var rc = [];
      if (showInc) { rc.push(['Bookings', function(r){ return r.count; }]); rc.push(['Income', function(r){ return pesoN(r.billed); }]); }
      if (showExp) { rc.push(['Agent pay', function(r){ return pesoN(r.agentPay); }]); rc.push(['Other expenses', function(r){ return pesoN(r.expenses); }]); }
      if (showNet) rc.push(['Net', function(r){ return pesoN(r.billed - r.agentPay - r.expenses); }]);
      bResort = '<h4>By resort</h4><table class="rt"><tr><th>Resort</th>' + rc.map(function(c){ return '<th class="r">' + c[0] + '</th>'; }).join('') + '</tr>';
      d.byResort.forEach(function(r){ bResort += '<tr><td>' + esc(r.resort) + '</td>' + rc.map(function(c){ return '<td class="r">' + c[1](r) + '</td>'; }).join('') + '</tr>'; });
      if (!d.byResort.length) bResort += emptyRow(rc.length + 1, 'No records.');
      bResort += '</table>';
    }
    var incBlocks = [];
    if (showInc) {
      var bType = '<h4>By booking type</h4><table class="rt"><tr><th>Type</th><th class="r">Bookings</th><th class="r">Income</th></tr>';
      d.byType.forEach(function(t){ bType += '<tr><td>' + esc(t.label) + '</td><td class="r">' + t.count + '</td><td class="r">' + pesoN(t.billed) + '</td></tr>'; });
      if (!d.byType.length) bType += emptyRow(3, 'No bookings.');
      bType += '</table>';
      var bPay = bResort;
      if (f.resort) {
        bPay = '<h4>Payments received</h4><table class="rt"><tr><th>Mode of payment</th><th class="r">Bookings</th><th class="r">Down payments</th></tr>';
        d.modes.forEach(function(m){ bPay += '<tr><td>' + esc(m.mode) + '</td><td class="r">' + m.count + '</td><td class="r">' + pesoN(m.dp) + '</td></tr>'; });
        if (!d.modes.length) bPay += emptyRow(3, 'No bookings.');
        bPay += '</table>';
      }
      var bFees = '<h4>Additional fees earned</h4><table class="rt"><tr><th>Fee</th><th class="r">Qty</th><th class="r">Amount</th></tr>';
      d.fees.forEach(function(x){ bFees += '<tr><td>' + esc(x.name) + '</td><td class="r">' + x.qty + '</td><td class="r">' + pesoN(x.amount) + '</td></tr>'; });
      if (!d.fees.length) bFees += emptyRow(3, 'None.');
      bFees += '</table>';
      var bCancel = '<h4>Cancellations and collections</h4><table class="rt">' +
         '<tr><td>Canceled bookings</td><td class="r">' + T.canceled + '</td></tr>' +
         '<tr><td>Value of canceled bookings</td><td class="r">' + pesoN(T.canceledValue) + '</td></tr>' +
         '<tr><td>Down payments received</td><td class="r">' + pesoN(T.downPayments) + '</td></tr>' +
         '<tr><td>Balance payments confirmed</td><td class="r">' + pesoN(T.balancePaid) + '</td></tr>' +
         '<tr><td>Extra charges logged after stays</td><td class="r">' + pesoN(T.extraCharges) + '</td></tr>' +
         '<tr><td>Total balance on bookings</td><td class="r">' + pesoN(T.balance) + '</td></tr>' +
         '<tr><td>Balance on upcoming bookings</td><td class="r">' + pesoN(T.pendingUpcoming) + '</td></tr></table>';
      incBlocks = [bType, bPay, bFees, bCancel];
    }
    h += pair(incBlocks);

    // ---- expense blocks ----
    if (showExp) {
      var bET = '<h4>Other expenses by type</h4><table class="rt"><tr><th>Type</th><th class="r">Records</th><th class="r">Amount</th><th class="r">Share</th></tr>';
      d.expByType.forEach(function(t){ bET += '<tr><td>' + esc(t.type) + '</td><td class="r">' + t.count + '</td><td class="r">' + pesoN(t.amount) + '</td><td class="r">' + (T.expenses ? Math.round(t.amount * 1000 / T.expenses) / 10 : 0) + '%</td></tr>'; });
      if (!d.expByType.length) bET += emptyRow(4, 'No expenses recorded in this period.');
      else bET += '<tr class="tot"><td>Total</td><td class="r">' + T.expCount + '</td><td class="r">' + pesoN(T.expenses) + '</td><td></td></tr>';
      bET += '</table>';
      var bEI = '<h4>Biggest expenses by item</h4><table class="rt"><tr><th>Item</th><th>Type</th><th class="r">Records</th><th class="r">Amount</th></tr>';
      d.expItems.forEach(function(x){ bEI += '<tr><td>' + esc(x.name) + '</td><td>' + esc(x.type) + '</td><td class="r">' + x.count + '</td><td class="r">' + pesoN(x.amount) + '</td></tr>'; });
      if (!d.expItems.length) bEI += emptyRow(4, 'No expenses recorded in this period.');
      bEI += '</table>';
      h += pair([!showInc ? bResort : '', bET, bEI]);

      var showRes = !f.resort;
      h += '<div class="rsec"><h4>Expense details</h4><table class="rt"><tr><th>Date paid</th>' + (showRes ? '<th>Resort</th>' : '') + '<th>Description</th><th>Paid to</th><th>Type</th><th class="r">Amount</th></tr>';
      d.expList.forEach(function(x){
        h += '<tr><td>' + esc(fmtDate(x.date)) + '</td>' + (showRes ? '<td>' + esc(x.resort) + '</td>' : '') + '<td>' + esc(x.description) + '</td><td>' + esc(x.paidTo) + '</td><td>' + esc(x.type) + '</td><td class="r">' + pesoN(x.amount) + '</td></tr>';
      });
      if (!d.expList.length) h += emptyRow(showRes ? 6 : 5, 'No expenses recorded in this period. Add them from Resort Expenses on the main menu.');
      else h += '<tr class="tot"><td colspan="' + (showRes ? 5 : 4) + '">Total of other expenses' + (d.expListMore ? ' (' + d.expListMore + ' older records are not listed but are counted)' : '') + '</td><td class="r">' + pesoN(T.expenses) + '</td></tr>';
      h += '</table></div>';
    }

    // ---- return of investment ----
    if (showRoi) h += roiHTML(d, f);

    var notes = [];
    if (showInc) notes.push('Income is the booking fee plus additional fees plus any extra charges logged after the stay, for active bookings (canceled bookings are excluded). The refundable security deposit is not counted.');
    if (showExp) notes.push('Expenses are the agent pay on referred bookings plus the expenses recorded under Resort Expenses, which are counted by the date they were paid.');
    if (showNet) notes.push('Net income is income minus all expenses.');
    if (showRoi) notes.push('Return of investment compares the net income of a rented resort, from its rent start date until today (every record if no start date is set), with the total rent. It does not depend on the report dates chosen above. The rent itself is not counted as an expense, so do not record rent payments under Resort Expenses.');
    h += '<div class="rnote">' + notes.join(' ') + '</div>';
    $('repContent').innerHTML = h;
    Array.prototype.forEach.call($('repContent').querySelectorAll('table.rt'),function(table){
      var wrap=document.createElement('div');wrap.className='report-table-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Financial report table');
      table.parentNode.insertBefore(wrap,table);wrap.appendChild(table);
    });
  }
  // PDF generation uses the report already on screen; exporting makes no Sheets requests.
  var pdfLibraries = null;
  function loadPdfLibraries() {
    if (window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.API.autoTable) return Promise.resolve();
    if (pdfLibraries) return pdfLibraries;
    function script(src) { return new Promise(function(resolve,reject){ var tag=document.createElement('script'); tag.src=src; tag.onload=resolve; tag.onerror=function(){tag.remove();reject(new Error('PDF tools could not load. Check your connection and try again.'));}; document.head.appendChild(tag); }); }
    pdfLibraries = (window.jspdf && window.jspdf.jsPDF ? Promise.resolve() : script('https://cdn.jsdelivr.net/npm/jspdf@4.2.1/dist/jspdf.umd.min.js'))
      .then(function(){return script('https://cdn.jsdelivr.net/npm/jspdf-autotable@5.0.7/dist/jspdf.plugin.autotable.min.js');})
      .catch(function(e){pdfLibraries=null;throw e;});
    return pdfLibraries;
  }
  function pdfText(value) {
    return String(value || '').replace(/₱/g,'PHP ').replace(/[–—−]/g,'-').replace(/·/g,' | ').replace(/≥/g,'>=').replace(/≤/g,'<=');
  }
  function downloadReportPdf() {
    if (!repData || !repLoadedFilters || !$('repContent').innerHTML) { $('repMsg').textContent='Build the report first.'; return; }
    var root=$('repContent').cloneNode(true), filters=Object.assign({},repLoadedFilters), button=$('btnRepDl');
    button.disabled=true; $('repMsg').textContent='Creating PDF…';
    loadPdfLibraries().then(function(){
      var doc=new window.jspdf.jsPDF({orientation:'portrait',unit:'pt',format:'a4',compress:true});
      var W=doc.internal.pageSize.getWidth(),H=doc.internal.pageSize.getHeight(),margin=40,y=76;
      function textOf(node){return pdfText((node.innerText || node.textContent || '').replace(/\s+/g,' ').trim());}
      function room(height){if(y+height>H-46){doc.addPage();y=54;}}
      function paragraph(value,heading){
        if(!value)return;var size=heading?11:9;doc.setFont('helvetica',heading?'bold':'normal');doc.setFontSize(size);var lines=doc.splitTextToSize(pdfText(value),W-margin*2);
        room(heading?Math.max(50,lines.length*14+12):lines.length*13+10);
        doc.setFont('helvetica',heading?'bold':'normal');doc.setFontSize(size);doc.setTextColor(heading?11:55,heading?109:75,heading?121:82);
        lines.forEach(function(line){room(14);doc.text(line,margin,y);y+=13;});y+=heading?9:8;
      }
      function table(head,body){
        if(!body.length&&!head.length)return;room(48);
        doc.autoTable({head:head,body:body,startY:y,margin:{top:54,left:margin,right:margin,bottom:44},theme:'striped',
          styles:{font:'helvetica',fontSize:8.5,cellPadding:5,overflow:'linebreak',textColor:[23,51,58],lineColor:[220,231,233],lineWidth:.2},
          headStyles:{fillColor:[8,117,129],textColor:255,fontStyle:'bold'},alternateRowStyles:{fillColor:[244,249,249]},rowPageBreak:'avoid'});
        y=doc.lastAutoTable.finalY+16;
      }
      var subtitle=root.querySelector('.rp-h .sub');paragraph(subtitle?textOf(subtitle):'');
      var generated=root.querySelector('.rp-h .gen');paragraph(generated?textOf(generated):'');
      function walk(container){Array.prototype.forEach.call(container.children,function(node){
        if(node.matches('.rp-h,.bar'))return;
        if(node.matches('.kpis')){
          table([['Metric','Value','Details']],Array.prototype.map.call(node.children,function(k){return [textOf(k.querySelector('.l')),textOf(k.querySelector('.v')),k.querySelector('.s')?textOf(k.querySelector('.s')):''];}));
        }else if(node.tagName==='TABLE'){
          var rows=Array.prototype.slice.call(node.rows),omit={};
          rows.forEach(function(row){Array.prototype.forEach.call(row.cells,function(cell,i){if(cell.querySelector('.bar'))omit[i]=true;});});
          var head=[],body=[];
          rows.forEach(function(row){var cells=Array.prototype.filter.call(row.cells,function(_,i){return !omit[i];}).map(function(cell){return {content:textOf(cell),colSpan:cell.colSpan||1,styles:{halign:cell.classList.contains('r')?'right':'left',fontStyle:row.classList.contains('tot')?'bold':'normal'}};});if(row.querySelector('th'))head.push(cells);else body.push(cells);});
          table(head,body);
        }else if(/^H[3-5]$/.test(node.tagName)){paragraph(textOf(node),true);}
        else if(node.querySelector('table,.kpis,h4,h5'))walk(node);
        else paragraph(textOf(node),false);
      });}
      walk(root);
      var pages=doc.getNumberOfPages();
      for(var i=1;i<=pages;i++){
        doc.setPage(i);doc.setFont('helvetica','bold');doc.setFontSize(i===1?19:10);doc.setTextColor(23,51,58);
        doc.text('Financial Report',margin,i===1?42:30);doc.setDrawColor(220,231,233);doc.line(margin,H-32,W-margin,H-32);
        doc.setFont('helvetica','normal');doc.setFontSize(8);doc.setTextColor(91,111,117);doc.text('Page '+i+' of '+pages,W-margin,H-19,{align:'right'});
      }
      var period=filters.mode==='range'?filters.from+'_to_'+filters.to:filters.year+(filters.mode==='month'?'-'+pad2(filters.month):'');
      var name='Financial-Report_'+(filters.resort||'All-Resorts').replace(/[^a-z0-9]+/gi,'-')+'_'+period+'_'+filters.view+'.pdf';
      doc.save(name);$('repMsg').textContent='PDF downloaded.';
    }).catch(function(e){$('repMsg').textContent='Could not create the PDF: '+e.message;}).finally(function(){button.disabled=!repData;});
  }

  /* ---------- resort expenses ---------- */
  var EXPENSES = [], exEdit = null, exPendingDel = null, EX_MAX = 8;
  function exMsg(t, c) { admMsg('exMsg', t, c); }
  function todayIso() { var t = new Date(); return t.getFullYear() + '-' + pad2(t.getMonth() + 1) + '-' + pad2(t.getDate()); }
  function exFind(id) { var f = null; EXPENSES.forEach(function(x){ if (x.id === id) f = x; }); return f; }
  function exInitFilters() {
    var h = '<option value="">All months</option>';
    MONTHS.forEach(function(m, i){ h += '<option value="' + (i + 1) + '">' + m + '</option>'; });
    $('exfMonth').innerHTML = h;
    $('exfYear').innerHTML = '<option value="">All years</option>';
  }
  function fillExYears() {
    var ys = {}, cur = $('exfYear').value;
    ys[String(new Date().getFullYear())] = 1;
    EXPENSES.forEach(function(e){ if (e.datePaid) ys[e.datePaid.slice(0, 4)] = 1; });
    var list = Object.keys(ys).sort().reverse();
    $('exfYear').innerHTML = '<option value="">All years</option>' + list.map(function(y){ return '<option>' + y + '</option>'; }).join('');
    $('exfYear').value = list.indexOf(cur) > -1 ? cur : '';
  }
  function topValues(key) {       // previously used descriptions / payees, most used first (for the suggestions)
    var c = {}, canon = {};
    EXPENSES.forEach(function(e){ var v = e[key]; if (!v) return; var k = v.toLowerCase(); if (!canon[k]) canon[k] = v; c[k] = (c[k] || 0) + 1; });
    return Object.keys(c).sort(function(a, b){ return c[b] - c[a] || (canon[a] < canon[b] ? -1 : 1); }).slice(0, 60).map(function(k){ return canon[k]; });
  }
  function fillExLists() {
    var opt = function(v){ return '<option value="' + attr(v) + '">'; };
    $('exDescList').innerHTML = topValues('description').map(opt).join('');
    $('exPayeeList').innerHTML = topValues('paidTo').map(opt).join('');
  }
  function exMatches(e) {
    var rf = $('exfResort').value, yr = $('exfYear').value, mo = $('exfMonth').value, ty = $('exfType').value, q = $('exfSearch').value.trim().toLowerCase();
    if (rf && e.resort !== rf) return false;
    if (yr && String(e.datePaid).slice(0, 4) !== yr) return false;
    if (mo && Number(String(e.datePaid).slice(5, 7)) !== Number(mo)) return false;
    if (ty && e.type !== ty) return false;
    if (q && (e.description + ' ' + e.paidTo).toLowerCase().indexOf(q) < 0) return false;
    return true;
  }
  function renderExpenses() {
    var rows = EXPENSES.filter(exMatches), tot = 0, prod = 0, svc = 0;
    rows.forEach(function(e){ tot += e.amount; if (e.type === 'Service') svc += e.amount; else prod += e.amount; });
    var kp = function(cls, l, v, s){ return '<div class="kpi ' + cls + '"><div class="l">' + l + '</div><div class="v">' + v + '</div>' + (s ? '<div class="s">' + s + '</div>' : '') + '</div>'; };
    $('exSum').innerHTML = kp('exp', 'Total spent', pesoE(tot), rows.length + ' record' + (rows.length === 1 ? '' : 's')) +
      kp('', 'Products', pesoE(prod), 'Things bought') + kp('', 'Services', pesoE(svc), 'Repairs, bills and other services');
    if (!rows.length) {
      $('exList').innerHTML = '<div class="empty">' + (EXPENSES.length ? 'No expenses match these filters.' : 'No expenses recorded yet. Press "+ Add Expense" to record the first one.') + '</div>';
      return;
    }
    $('exList').innerHTML = rows.map(function(e){
      var svcCls = e.type === 'Service';
      return '<div class="exp-card' + (svcCls ? ' svc' : '') + '"><div class="exp-main"><b>' + esc(e.description) + '</b> <span class="chip">' + esc(e.resort) + '</span>' +
        '<span class="badge ' + (svcCls ? 'svc' : 'prod') + '">' + esc(e.type) + '</span>' +
        '<div class="exp-meta">Paid to: ' + esc(e.paidTo) + '<br>Date paid: ' + esc(fmtDate(e.datePaid)) + ' &middot; ' + esc(e.id) + '</div>' +
        '<div class="actions">' +
          (e.photos ? '<button type="button" class="btn-photos" data-ex-photos="' + attr(e.id) + '">View photos (' + e.photos + ')</button>' : '') +
          '<button type="button" class="btn-edit" data-ex-edit="' + attr(e.id) + '">Edit</button>' +
          '<button type="button" class="btn-cancel" data-ex-del="' + attr(e.id) + '">Delete</button>' +
        '</div></div><div class="exp-amt">' + esc(peso(e.amount)) + '</div></div>';
    }).join('');
  }
  function loadExpenses(cb) {
    if (!(window.google && google.script)) { EXPENSES = []; renderExpenses(); return; }
    exMsg('Loading expenses...');
    RUN
      .withSuccessHandler(function(list){ EXPENSES = list || []; exMsg(''); fillExYears(); fillExLists(); renderExpenses(); if (cb) cb(); })
      .withFailureHandler(function(e){ if (authFail(e)) return; exMsg('Could not load the expenses: ' + e.message, 'err'); })
      .getExpenses(TOKEN);
  }
  function openExpenses() {
    if (!$('exfMonth').innerHTML) exInitFilters();
    showScreen('expenses');
    exMsg('');
    loadExpenses();
  }

  // ----- add / edit form -----
  function exTypeVal() { var r = document.querySelector('input[name=exType]:checked'); return r ? r.value : ''; }
  function renderExPhotos() {
    $('ex_photos').innerHTML = exEdit.items.map(function(p, i){
      var inner = p.data ? '<img src="' + p.data + '" alt="Photo ' + (i + 1) + '">' : (p.missing ? 'Not found in Drive' : (p.failed ? 'Could not load' : 'Loading...'));
      return '<div class="ph">' + inner + '<button type="button" class="rmx" data-rm="' + i + '" title="Remove this photo">&times;</button></div>';
    }).join('');
    $('ex_photoHint').textContent = exEdit.items.length + ' of ' + EX_MAX + ' photos attached. Tap the x on a photo to remove it.';
  }
  function openExpenseForm(id) {
    var e = id ? exFind(id) : null;
    if (id && !e) return;
    var my = exEdit = {id: id || '', items: []};
    $('exTitle').textContent = e ? 'Edit expense' : 'Add expense';
    $('ex_lblAmt').textContent = 'Amount paid (' + CUR + ') *';
    var def = e ? e.resort : ($('exfResort').value || $('resort').value || DEFAULT_RESORT);
    if (CFG.resorts.some(function(r){ return r.name === def; })) $('ex_resort').value = def;
    $('ex_desc').value = e ? e.description : '';
    $('ex_date').value = e ? e.datePaid : todayIso();
    $('ex_amt').value = e ? e.amount : '';
    $('ex_to').value = e ? e.paidTo : '';
    Array.prototype.forEach.call(document.querySelectorAll('input[name=exType]'), function(r){ r.checked = !!e && r.value === e.type; });
    $('ex_files').value = ''; admMsg('exFormMsg', '');
    if (e && e.photoIds.length) {
      my.items = e.photoIds.map(function(pid){ return {old: true, id: pid, data: ''}; });
      RUN
        .withSuccessHandler(function(list){
          if (exEdit !== my) return;
          (list || []).forEach(function(p){ my.items.forEach(function(it){ if (it.old && it.id === p.id) { it.data = p.data || ''; it.missing = !!p.missing; } }); });
          renderExPhotos();
        })
        .withFailureHandler(function(){ if (exEdit !== my) return; my.items.forEach(function(it){ if (it.old && !it.data) it.failed = true; }); renderExPhotos(); })
        .getExpensePhotos(TOKEN, id);
    }
    renderExPhotos();
    $('btnExSave').disabled = false;
    $('exBg').style.display = 'flex';
  }
  function closeExpenseForm() { $('exBg').style.display = 'none'; exEdit = null; $('ex_photos').innerHTML = ''; }
  // shrink a chosen photo in the browser before it is sent (keeps uploads small and fast)
  function exShrink(file, cb) {
    var rd = new FileReader();
    rd.onerror = function(){ cb(''); };
    rd.onload = function(ev){
      var img = new Image();
      img.onload = function(){
        var sc = Math.min(1, 1100 / Math.max(img.width, img.height));
        var c = document.createElement('canvas'); c.width = Math.max(1, Math.round(img.width * sc)); c.height = Math.max(1, Math.round(img.height * sc));
        var g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);
        cb(c.toDataURL('image/jpeg', 0.78));
      };
      img.onerror = function(){ cb(''); };
      img.src = ev.target.result;
    };
    rd.readAsDataURL(file);
  }
  function addExFiles(fileList) {
    if (!exEdit) return;
    var files = Array.prototype.slice.call(fileList || []), room = EX_MAX - exEdit.items.length, my = exEdit;
    if (!files.length) return;
    if (files.length > room) {
      admMsg('exFormMsg', 'You can attach up to ' + EX_MAX + ' photos to one expense. ' + (room > 0 ? 'Only the first ' + room + ' were added.' : 'Remove a photo first.'), 'err');
      files = files.slice(0, Math.max(room, 0));
    } else { admMsg('exFormMsg', ''); }
    var done = 0, got = [];
    files.forEach(function(f, i){
      exShrink(f, function(data){
        got[i] = data;
        if (++done < files.length || exEdit !== my) return;
        var added = 0;
        got.forEach(function(d){ if (d) { my.items.push({old: false, data: d}); added++; } });
        if (added < got.length) admMsg('exFormMsg', 'Some files could not be read as pictures and were skipped.', 'err');
        renderExPhotos();
      });
    });
  }
  function saveExpenseForm() {
    if (!exEdit) return;
    var my = exEdit;
    var d = {id: my.id, resort: $('ex_resort').value, description: $('ex_desc').value.trim(), datePaid: $('ex_date').value,
             amount: parseFloat($('ex_amt').value), paidTo: $('ex_to').value.trim(), type: exTypeVal(), keep: [], add: []};
    var msg = '';
    if (!d.resort) msg = 'Please choose the resort.';
    else if (!d.description) msg = 'Please enter the description or name of the expense, for example Electricity.';
    else if (!d.datePaid) msg = 'Please enter the date paid.';
    else if (!(d.amount > 0)) msg = 'Please enter the amount paid (more than 0).';
    else if (!d.paidTo) msg = 'Please enter who the payment was made to.';
    else if (!d.type) msg = 'Please choose the expense type: Product or Service.';
    if (msg) { admMsg('exFormMsg', msg, 'err'); return; }
    my.items.forEach(function(it){ if (it.old) d.keep.push(it.id); else d.add.push(it.data); });
    var btn = $('btnExSave');
    setBusy(btn, true, d.add.length ? 'Uploading...' : 'Saving...'); admMsg('exFormMsg', '');
    RUN
      .withSuccessHandler(function(r){
        setBusy(btn, false);
        if (!r.ok) { admMsg('exFormMsg', r.message, 'err'); return; }
        closeExpenseForm();
        var verb = d.id ? 'updated' : 'added';
        loadExpenses(function(){
          var saved = exFind(r.id);
          if (saved && !exMatches(saved)) exMsg('Expense ' + verb + ', but your filters hide it. Set the filters to "All" to see it.', 'ok');
          else exMsg('Expense ' + verb + '.', 'ok');
        });
      })
      .withFailureHandler(function(e){ setBusy(btn, false); if (authFail(e)) return; admMsg('exFormMsg', 'Could not save: ' + e.message, 'err'); })
      .saveExpense(TOKEN, d);
  }

