  // the PIN is typed twice; returns it, or '' after showing what is wrong
  function pinPair(a, b) {
    var p1 = $(a).value, p2 = $(b).value;
    if (!/^\d{6}$/.test(p1)) { licMsg('Choose a PIN of exactly 6 digits.'); $(a).focus(); return ''; }
    if (p1 !== p2) { licMsg('The two PINs do not match. Please type them again.'); $(b).value = ''; $(b).focus(); return ''; }
    if (p1 === '123456' || p1 === '654321' || p1 === '012345' || /^(\d)\1{5}$/.test(p1)) { licMsg('That PIN is too easy to guess. Choose a different one.'); $(a).focus(); return ''; }
    return p1;
  }
  // "Finish setting up": the client's own sheet is created (in the provider's Google Drive) and their PIN is saved in it
