    var on = !!(l && l.enabled && l.allowed), days = on ? licDays(l) : '';
    $('lnkPinKey').style.display = (on && l.hosted && !PROVIDER) ? 'inline-block' : 'none';
    $('pinSub').textContent = !on ? '' : [l.signedInAs ? 'Signed in as ' + l.signedInAs : '', l.tier ? l.tier + ' plan' : '', l.lifetime ? '' : days].filter(Boolean).join('  |  ');
    var b = $('btnSub');
    b.style.display = on ? '' : 'none';
    clearTimeout(licTimer); licTimer = null;
    if (!on) { $('subBanner').innerHTML = ''; $('subBody').innerHTML = ''; return; }
    // lock this page at the exact moment the subscription ends (the server refuses every call from then on anyway)
    if (l.expiresAt && !l.adminView) {
      var ms = l.expiresAt - (l.now || Date.now());
      if (ms < 2000000000) licTimer = setTimeout(function(){ lockApp(''); bootLicense(true); }, Math.max(ms, 0) + 1500);
    }
    b.innerHTML = '&#9203; ' + esc(days || 'Subscription'); b.className = 'sub-btn' + (l.warn ? ' lic-soon' : '');
