      '<input class="pin-input" id="payPin" type="password" inputmode="numeric" pattern="[0-9]*" maxlength="6" autocomplete="off" placeholder="------">' +
      '<div class="adm-msg" id="payMsg"></div><button class="primary" id="btnPayPin" type="button" style="width:100%;margin-top:8px">Continue</button>';
